const HOMOEOPATHIE_FAELLE = [
  { route:"homoeopathie-fall-1", typ:1, subtyp:"SE1", titel:"Patient vom Typ 1", krankheit:"Chronisch-entz\xfcndliche Darmerkrankung", heilmittel:"Platinum metallicum", teaser:"Mann, 51 Jahre. Aristokratische Blickqualit\xe4t, hohe Prinzipien, Perfektionismus. Colitis ulcerosa mit blutigen Durchf\xe4llen. Die unbewusst gelebte Grundleidenschaft des Zorns \xe4u\xdfert sich als Entz\xfcndung im Darm. Eine drohende Operation kann durch das Enneagramm-Heilmittel Platin vollst\xe4ndig abgewendet werden." },
  { route:"homoeopathie-fall-2", typ:2, subtyp:"SO2", titel:"Patientin vom Typ 2", krankheit:"Unerf\xfcllter Kinderwunsch", heilmittel:"Hyoscyamus niger", teaser:"Frau, 37 Jahre. Liebesorientiert, emotional offen, hilfreich und gro\xdfz\xfcgig. Drei Jahre ungew\xfcnschte Kinderlosigkeit, dazu Bulimie-Phasen und Harnwegsinfekte. Thema: entt\xe4uschte Liebe und der Wunsch nach Verbindung. Das Bilsenkraut gibt der Lebenskraft die n\xf6tige Resonanz." },
  { route:"homoeopathie-fall-3", typ:3, subtyp:"SX3", titel:"Patient vom Typ 3", krankheit:"Burnout-Syndrom & Restless-Legs-Syndrom", heilmittel:"Tarantula hispanica", teaser:"Mann, 46 Jahre. Koch, Workaholic, gef\xfchlskalter Blick, versteinerter Ausdruck. Burnout und ruhelose Beine mit Gef\xfchlsst\xf6rungen. Die blockierte Herz-Energie des Dreiers sucht einen K\xf6rper-Ausweg. Tarantula hispanica l\xf6st nach vier Monaten noch den entscheidenden Durchbruch aus." },
  { route:"homoeopathie-fall-4", typ:4, subtyp:"SX4", titel:"Patientin vom Typ 4", krankheit:"Alkoholsucht & Depression", heilmittel:"Ignatia amara", teaser:"Frau, 44 Jahre. Blond, gepflegt, dunkelbraune Augen. Chronisches Gef\xfchl, etwas Besseres zu sein. Regelm\xe4\xdfiger Alkoholkonsum seit 15 Jahren, Magenschleimhautentz\xfcndungen, Depression. Die Neid-Leidenschaft des Vierers \xe4u\xdfert sich als Abgrenzung vom eigenen Leben. Schrittweise Heilung \xfcber aufsteigende Potenzen." },
  { route:"homoeopathie-fall-5", typ:5, subtyp:"SO5", titel:"Patient vom Typ 5", krankheit:"H\xfcftschmerzen mit Aussicht auf H\xfcft-Operation", heilmittel:"Stramonium", teaser:"Mann, 51 Jahre. Gymnasiallehrer, horizontal verlaufende Stirnfalten, distanziert und nachdenklich. Coxalgie mit fortgeschrittener Arthrose, drohende H\xfcftoperation. Das Geiz-Muster des F\xfcnfers schw\xe4cht die Lebenskraft. Stramonium, der Stechapfel, gibt dem K\xf6rper seine Bewegungsfreiheit zur\xfcck." },
  { route:"homoeopathie-fall-6", typ:6, subtyp:"SE6", titel:"Patient vom Typ 6", krankheit:"Versagens\xe4ngste", heilmittel:"Opium", teaser:"Mann, 53 Jahre, Schulleiter. Starkes Schwitzen unter Druck, Konzentrations- und Wortfindungsst\xf6rungen, sexuelle Probleme. Die Angst als Grundleidenschaft l\xe4hmt ihn zunehmend. Opium, der Schlafmohn, entsperrt die blockierte Kopfenergie und schenkt ihm nach zwei Jahren therapeutischer Arbeit innere Souver\xe4nit\xe4t." },
  { route:"homoeopathie-fall-7", typ:7, subtyp:"SX7", titel:"Patientin vom Typ 7", krankheit:"Starke migr\xe4neartige Kopfschmerzen", heilmittel:"Belladonna", teaser:"Frau, 27 Jahre. Verk\xe4uferin, lebhaft und optimistisch, warmer fr\xf6hlicher Blick, rote Wangen. Migr\xe4neartige Kopfschmerzen und Gallensteinkoliken seit Jahren. Die Ma\xdflosigkeit des Siebeners sucht \xfcber starke k\xf6rperliche Symptome ein Gleichgewicht. Belladonna, die Tollkirsche, bringt Entspannung und vollst\xe4ndige Heilung." },
  { route:"homoeopathie-fall-8", typ:8, subtyp:"SE8", titel:"Patient vom Typ 8", krankheit:"Manische Depression", heilmittel:"Veratrum album", teaser:"Mann, 44 Jahre. Garten- und Landschaftsbauer. Bipolare St\xf6rung mit Maniephasen (f\xfchlte sich als Nachfolger Jesu Christi) und suizidalen Depressionen. Mehrere Psychiatrie-Aufenthalte. Die \xfcberentwickelte Bauchenergie der Acht findet keinen nat\xfcrlichen Kanal. Veratrum album, der wei\xdfe Germer, bringt schrittweise Stabilit\xe4t." },
  { route:"homoeopathie-fall-9", typ:9, subtyp:"SE9", titel:"Patient vom Typ 9", krankheit:"Rezidivierende H\xe4morrhoidalblutungen", heilmittel:"Cannabis indica", teaser:"Mann, 53 Jahre. 96 kg, BMI 31, Adipositas Grad I. Rezidivierende H\xe4morrhoidalblutungen, Fettleber, sitzende T\xe4tigkeit, Fast-Food-Ern\xe4hrung, 9\u201310 Stunden Schlaf t\xe4glich. Die Tr\xe4gheit als Grundleidenschaft des Neuners sperrt die Lebenskraft. Cannabis indica, der Indische Hanf, l\xf6st die tief verwurzelte k\xf6rperliche Stagnation." },
];

function enneagrammHomoeopathiePage() {
  function card(f) {
    const col = (typeof TYPE_COLORS !== 'undefined' ? TYPE_COLORS[f.typ] : null) || 'var(--copper)';
    return `<div class="kf-card" data-route="${f.route}" onclick="go('${f.route}')" style="cursor:pointer;border-radius:10px;border:1px solid var(--border);padding:1rem 1.1rem;background:var(--ivory);">
      <div style="display:flex;align-items:center;gap:0.6rem;margin-bottom:0.3rem;">
        <span style="font-size:0.7rem;font-weight:700;letter-spacing:0.12em;text-transform:uppercase;color:${col};">Typ ${f.typ}</span>
        <span style="font-size:0.7rem;color:var(--muted);background:var(--paper);border:1px solid var(--line);border-radius:20px;padding:0.1rem 0.55rem;">${f.heilmittel}</span>
      </div>
      <div style="font-weight:700;font-size:1rem;color:var(--ink);margin-bottom:0.15rem;">${f.krankheit}</div>
      <div style="font-size:0.85rem;color:var(--muted);line-height:1.5;">${f.teaser}</div>
    </div>`;
  }
  return shell(`
    <div class="page-container">
      ${pageHeader('enneagramm-homoeopathie')}
      <div class="page-content">
        <p class="eyebrow">Wissen &middot; Heilkunde</p>
        <h1 class="section-title">Enneagramm meets Hom\xf6opathie</h1>

        <blockquote class="vb-blockquote" style="margin-bottom:1.8rem;">
          <p class="vb-intro">Jeder Mensch besitzt im Kern seiner Pers\xf6nlichkeit eine vorherrschende, ihm aber in aller Regel verborgene <strong>Grundleidenschaft</strong>. Diese ist die wahre Ursache f\xfcr sein Kranksein und sein Leid &ndash; denn sie ist die unbewusste Leidenschaft, die Leiden schafft. Menschen leben ihre Hauptleidenschaft (Zorn, Stolz, Eitelkeit, Neid, Geiz, Angst, Ma\xdflosigkeit, Gier oder Tr\xe4gheit) stets ein- und \xfcberseitig und erkranken auf Dauer genau daran.</p>
          <p class="vb-intro">Die <strong>Enneagramm-Hom\xf6opathie</strong> (kurz: EH) verbindet die ca. 5000 Jahre alte Menschentypenlehre des Enneagramms mit der \xfcber 200 Jahre alten Hom\xf6opathie nach Dr. Samuel Hahnemann. Sie erm\xf6glicht Heilung auf dieser tiefsten Ebene des Menschseins, indem sie durch die Gabe eines hom\xf6opathischen Einzelmittels die verborgene Grundleidenschaft des Patienten und damit auch seine individuelle Lebenskraft wieder ins Gleichgewicht bringt. Entsprechend dieser 9 Grundleidenschaften gibt es auf der Essenz-Ebene nur <strong>neun spezifische hom\xf6opathische Heilmittel</strong>, je eines f\xfcr jeden Enneagrammtyp.</p>
          <p class="vb-intro">Schon der Begr\xfcnder der Hom\xf6opathie, Dr. Samuel Hahnemann, erkannte: <em>&bdquo;Das Gem\xfct ist der Schl\xfcssel zur Heilung des Patienten.&ldquo;</em> Die Enneagramm-Hom\xf6opathie geht noch einen Schritt tiefer &ndash; zum unbewussten Kern des Gem\xfcts, der Enneagrammfixierung.</p>
        </blockquote>

        <div style="margin:0 0 2rem;border-radius:12px;overflow:hidden;box-shadow:0 2px 12px rgba(0,0,0,0.15);">
          <img src="./assets/schaubilder/heilungsweg-des-menschen.jpg" alt="Der Heilungsweg des Menschen &ndash; \xdcbersicht der 4 Heilungs-Ebenen" style="width:100%;display:block;" loading="lazy" />
          <p style="text-align:center;font-size:0.78rem;color:var(--muted);margin:0;padding:0.5rem 0.5rem 0.7rem;">Die vier Ebenen hom\xf6opathischer Heilung &ndash; von der k\xf6rperlichen bis zur Essenz-Ebene</p>
        </div>

        <h2 class="section-title" style="font-size:1.25rem;margin:0 0 1.2rem;">9 Patientenf\xe4lle aus der Praxis</h2>
        <p style="font-size:0.9rem;color:var(--muted);line-height:1.6;margin:0 0 1.4rem;">Die folgenden Fallberichte stammen aus der lebendigen Praxis der Enneagramm-Hom\xf6opathie. Alle Patienten sind anonymisiert. Die F\xe4lle zeigen exemplarisch, wie die Bestimmung des Enneagrammtyps und die Verordnung des typspezifischen Heilmittels wirkt &ndash; auf der tiefsten Ebene des Menschseins.</p>
        <div style="display:flex;flex-direction:column;gap:1rem;margin-bottom:2rem;">
          ${HOMOEOPATHIE_FAELLE.map(card).join('')}
        </div>

        ${bookTip("enneagramm-homoeopathie-band-1", "Das Grundlagenwerk der Enneagramm-Hom\u00f6opathie \u2013 wie Pers\u00f6nlichkeitstyp und Heilmittelwahl auf der tiefsten Ebene zusammenh\u00e4ngen.", "Enneagramm-Hom\u00f6opathie \u2013 Band 1")}
        ${bookTip("enneagramm-homoeopathie-band-2", "Weitere Fallberichte und Vertiefung der Enneagramm-Hom\u00f6opathie in Band 2.", "Enneagramm-Hom\u00f6opathie \u2013 Band 2")}
        ${relatedLinks([
          {route:"heilungsweg", label:"Schaubild: Heilungsweg des Menschen"},
          {route:"homoeopathie", label:"Hom\xf6opathie \u2013 Heilmittel\xfcbersicht"},
          {route:"wunden", label:"Die 9 Wunden der Enneagrammtypen"},
          {route:"beruehmte-samuel-hahnemann", label:"Portr\xe4t: Dr. Samuel Hahnemann (SO1w9)"},
          {route:"enneagramm-reflexzonentherapie", label:"Enneagramm meets Reflexzonentherapie"},
          {route:"enneagramm-zahnpsychosomatik", label:"Enneagramm meets Zahn-Psychosomatik"},
        ])}
      </div>
    </div>
  `);
}

function _homoeopathieFallPage(f) {
  const col = (typeof TYPE_COLORS !== 'undefined' ? TYPE_COLORS[f.typ] : null) || 'var(--copper)';
  const leidenschaften = ["","Zorn","Stolz","Eitelkeit","Neid","Geiz","Angst","Ma\xdflosigkeit","Gier","Tr\xe4gheit"];
  const leidenschaft = leidenschaften[f.typ] || "";
  return shell(`
    <div class="page-container">
      ${pageHeader('enneagramm-homoeopathie')}
      <div class="page-content">
        <button class="ghost-link" data-route="enneagramm-homoeopathie" style="margin-bottom:1.2rem;">&larr; Alle Fallberichte</button>
        <p class="eyebrow" style="color:${col};">Wissen &middot; Hom\xf6opathie &middot; Typ ${f.typ}</p>
        <h1 style="font-family:'EB Garamond',serif;font-size:1.9rem;color:var(--ink);margin:0.3rem 0 0.2rem;line-height:1.2;">${f.krankheit}</h1>
        <p style="font-size:0.85rem;color:var(--muted);margin:0 0 1.6rem;">${f.titel} &middot; Grundleidenschaft: ${leidenschaft} &middot; Heilmittel: <strong style="color:${col};">${f.heilmittel}</strong></p>

        <blockquote class="vb-blockquote" style="margin-bottom:1.6rem;">
          <p class="vb-intro">${f.fallbeschreibung}</p>
        </blockquote>

        <div class="vb-section" style="max-width:100%;">
          <h2 style="font-size:1rem;font-weight:700;color:var(--ink);margin:0 0 0.7rem;">Enneagramm-Diagnose</h2>
          <p class="vb-intro">${f.diagnose}</p>

          <h2 style="font-size:1rem;font-weight:700;color:var(--ink);margin:1.4rem 0 0.7rem;">Das hom\xf6opathische Heilmittel: ${f.heilmittel}</h2>
          <p class="vb-intro">${f.heilmitteltext}</p>

          <h2 style="font-size:1rem;font-weight:700;color:var(--ink);margin:1.4rem 0 0.7rem;">Verlauf &amp; Ergebnis</h2>
          <p class="vb-intro">${f.verlauf}</p>
        </div>

        ${bookTip("enneagramm-homoeopathie-band-1", "Das Grundlagenwerk der Enneagramm-Hom\u00f6opathie \u2013 wie Pers\u00f6nlichkeitstyp und Heilmittelwahl auf der tiefsten Ebene zusammenh\u00e4ngen.", "Enneagramm-Hom\u00f6opathie \u2013 Band 1")}
        ${bookTip("enneagramm-homoeopathie-band-2", "Weitere Fallberichte und Vertiefung der Enneagramm-Hom\u00f6opathie in Band 2.", "Enneagramm-Hom\u00f6opathie \u2013 Band 2")}
        ${relatedLinks([
          {route:"enneagramm-homoeopathie", label:"Alle 9 Patientenf\xe4lle"},
          {route:"heilungsweg", label:"Heilungsweg des Menschen (Schaubild)"},
          {route:"wunden", label:"Die 9 Wunden der Enneagrammtypen"},
        ])}
      </div>
    </div>
  `);
}

const HOMOEOPATHIE_FALL_DETAILS = {
  "homoeopathie-fall-1": {
    fallbeschreibung: "Ein 51-j\xe4hriger Patient kommt mit einer schwerwiegenden chronisch-entz\xfcndlichen Darmerkrankung (Colitis ulcerosa) in die Praxis &ndash; blutige Durchf\xe4lle, der K\xf6rper nahe an einer Operation. Er ist auf Empfehlung einer Freundin gekommen und m\xf6chte trotz zunehmender Symptomatik eine letzte M\xf6glichkeit der Naturheilkunde nutzen. Sein Auftreten ist aristokratisch: schmale Lippen, hagere Erscheinung, ernst-kritischer Blick. Er neigt zum Perfektionismus, stellt hohe Anspr\xfcche an sich und andere, und ist beruflich sehr leistungsorientiert. Er klagt auch \xfcber sexuelle Unlust und zahlreiche Allergien.",
    diagnose: "S\xe4mtliche Merkmale &ndash; die aristokratische Blickqualit\xe4t, die Rechthaberei, der Perfektionismus, die kritische Distanz und das Streben nach Makellosigkeit &ndash; weisen eindeutig auf den <strong>Enneagrammtyp 1</strong> hin. Seine Grundleidenschaft ist der <strong>Zorn</strong>: eine im Alltag unbewusst gelebte, einseitig ausagierte Aggressionsenergie, die sich nicht nach au\xdfen entl\xe4dt, sondern sich k\xf6rperlich in Form von Entz\xfcndungen im Darm manifestiert. Der Darm als Organ der Typ-1-Physiologie wird zum Spiegel der inneren emotionalen Verkrampfung.",
    heilmitteltext: "<strong>Platinum metallicum (Platin)</strong> ist das hom\xf6opathische Enneagramm-Heilmittel f\xfcr den Typ 1. Das edle Metall entspricht der inneren Haltung des Perfektionisten: aristokratisch, selbstanspruchsvoll, innerlich angespannt. In der Hom\xf6opathie wirkt Platin auf die Entspannung dieser \xfcberspannten Lebenskraft, l\xf6st den inneren Zorn auf essenzieller Ebene und erm\xf6glicht dem K\xf6rper, die Entz\xfcndungsspirale zu verlassen. Es wird in der typspezifischen, hom\u00f6opathisch angezeigten Dosierung und Potenz verordnet.",
    verlauf: "Innerhalb weniger Wochen nach Beginn der Mittelgabe verringern sich die schleimig-blutigen Durchf\xe4lle zusehends. Der Darm heilt vollst\xe4ndig ab. Eine Operation wird abgewendet. Auch der fr\xfchere Fu\xdfpilz verschwindet nach zwei Monaten. Der Patient berichtet, sich lebendiger, souver\xe4ner, gelassener und geduldiger zu f\xfchlen &ndash; auch im zwischenmenschlichen Bereich. Nach einem Jahr ist er nahezu beschwerdefrei. Einzig eine Allergie auf Haseln\xfcsse und Milchprodukte besteht fort, aber damit kann er nach eigenen Angaben \u201egut leben\u201c."
  },
  "homoeopathie-fall-2": {
    fallbeschreibung: "Eine 37-j\xe4hrige Patientin kommt mit dem Wunsch schwanger zu werden in die Praxis. Seit drei Jahren versucht sie vergeblich, eine Schwangerschaft zu erzielen. Sie leidet zus\xe4tzlich seit ihrer Jugend unter Phasen von Bulimie und st\xe4ndig wiederkehrenden Harnwegsinfekten. W\xe4hrend der Anamnese sitzt ihr eine sehr freundlich-gef\xe4llige, emotional offene und selbstbewusste Frau gegen\xfcber &ndash; bis das Thema Sterilit\u00e4t angesprochen wird: Dann senkt sich ihr Blick schlagartig, sie wird traurig, ihre Augen f\xfcllen sich mit Tr\xe4nen. Sie stellt sich stets als freigiebig und gro\xdfz\xfcgig dar und w\xfcrde f\xfcr eine Schwangerschaft einfach alles unternehmen.",
    diagnose: "Die liebesorientierte Blickqualit\xe4t, der starke Hilfs- und F\xfcrsorgedrang, das emotionale Ausdrucksverhalten, der Stolz gepaart mit tiefer Gutm\xfctigkeit &ndash; all das entspricht dem <strong>Enneagrammtyp 2</strong>. Seine Grundleidenschaft ist der <strong>Stolz</strong>: Die Unfruchtbarkeit und die damit verbundenen Entt\xe4uschungen in der Liebes-Dimension (kein Kind als Ausdruck der tiefsten Form von Liebe) treffen genau das unbewusste Kernthema des Typs 2. Bulimie und Harnwegsinfekte sind k\xf6rperliche Ausdrucksformen dieser emotionalen Dysbalance.",
    heilmitteltext: "<strong>Hyoscyamus niger (Schwarzes Bilsenkraut)</strong> ist das hom\xf6opathische Enneagramm-Heilmittel f\xfcr den Typ 2. Auf essenzieller Ebene adressiert es die Dynamik des entt\xe4uschten Verlangens nach Liebe und Zugeh\xf6rigkeit. Das Heilmittel wirkt auf die emotionale Lebenskraft des Typs 2 und schafft die Voraussetzungen, dass der K\xf6rper empf\xe4nglich f\xfcr das werden kann, was er tief begehrt.",
    verlauf: "Zwei Monate nach der Mittelgabe ruft die Patientin an: &bdquo;\u00dcberraschung &ndash; ich bin endlich schwanger und mir geht es wunderbar!&ldquo; Das hom\xf6opathische Enneagramm-Heilmittel hat die Lebenskraft der Patientin auf einer tieferen Ebene wieder ins energetische Gleichgewicht gebracht &ndash; und damit die K\xf6rperbedingungen f\xfcr die bislang erfolglos angestrebte Schwangerschaft geschaffen."
  },
  "homoeopathie-fall-3": {
    fallbeschreibung: "Ein 46-j\xe4hriger Koch kommt wegen eines Burnouts und ruheloser Beine mit Gef\xfchlsst\xf6rungen (Restless-Legs-Syndrom) in die Praxis. Sein Hausarzt hat ihn bereits drei Wochen krankgeschrieben. Auf psychischer Ebene dominieren bei ihm starke Verzweiflung, fortschreitendes Gef\xfchl der Wertlosigkeit, Existenz\xe4ngste und Phasen von Gleichg\xfcltigkeit. Sein Blick ist leer und gef\xfchlskalt, sein Gesicht versteinernd. Er arbeitet unerm\xfcdlich, nimmt zahlreiche \u00dcberstunden, hat hohe Erwartungen an das Leben und sieht sich als dynamischen, \xe4u\xdferlich erfolgreichen Menschen.",
    diagnose: "Der leer-gef\xfchlskalte Blick, das Workaholism-Muster, die soziale Fassade des Erfolgs hinter der ein emotional abgeschnittenes Innenleben steckt &ndash; das sind die unverwechselbaren Merkmale des <strong>Enneagrammtyps 3</strong>. Seine Grundleidenschaft ist die <strong>Eitelkeit</strong>: Die blockierte Herzenergie des Dreiers, die seine eigenen Gef\xfchle total abschneidet, sucht sich einen K\xf6rperausweg \xfcber das Nervensystem (Restless Legs) und f\xfchrt zum emotionalen Zusammenbruch (Burnout).",
    heilmitteltext: "<strong>Tarantula hispanica (Spanische Vogelspinne)</strong> ist das hom\xf6opathische Enneagramm-Heilmittel f\xfcr den Typ 3. Es entspricht der ruhelosen, hypermotorischen Energie, die keine Ruhe findet. In der Hom\xf6opathie wirkt Tarantula auf genau jene unruhige, getriebene Nervensystem-Energie und gibt dem K\xf6rper die M\xf6glichkeit, aus dem Burnout-Modus zur\xfcckzufinden.",
    verlauf: "Nach etwa vier Monaten mit wiederholt verordnetem Heilmittel in unterschiedlicher Dosierung gelingt ein sp\xfcrbarer Durchbruch: Die Beine werden ruhig, der Patient arbeitet wieder als Koch &ndash; ohne die fr\xfcheren \xdcberstunden. Er entwickelt durch die Besch\xe4ftigung mit dem Enneagrammtyp 3 eine neue Eigenwahrnehmung und lernt, zwischen Arbeitswelt und Privatleben eine klare Grenze zu ziehen. Die Familie profitiert nun von seiner Gesundheit."
  },
  "homoeopathie-fall-4": {
    fallbeschreibung: "Eine 44-j\xe4hrige Patientin kommt mit Depression und Alkoholsucht. Sie ist blond, gut gekleidet, gepflegt. Seit 15 Jahren trinkt sie regelm\xe4\xdfig gr\xf6\xdfere Mengen Alkohol, was sich in immer wiederkehrenden Magenschleimhautentz\xfcndungen zeigt. Sie erf\xe4hrt sich innerlich stets als besonders und glaubt, f\xfcr etwas Besseres bestimmt zu sein &ndash; findet aber dennoch keine wahre Erf\xfcllung. Ihren Mann hat sie vor drei Jahren verlassen, befindet sich seitdem in wechselnden Partnerschaften. Sie steht unter psychologischer Behandlung und nimmt t\xe4glich ein Antidepressivum. Durch Blickanalyse eines Fotos, das ihr der Therapeut zug\xe4nglich gemacht hatte, konnten bereits erste deutliche Hinweise auf den Enneagrammtyp 4 abgelesen werden.",
    diagnose: "Die tiefe Identifikation mit dem Einzigartigen, das chronische Gef\xfchl der Unvollst\xe4ndigkeit, das Suchen in Beziehungen nach dem &bdquo;wahren Ich&ldquo;, die Depressionsphasen als Ausdruck der Entt\u00e4uschungs-Dynamik &ndash; all das verweist auf den <strong>Enneagrammtyp 4</strong>. Seine Grundleidenschaft ist der <strong>Neid</strong>: das Gef\xfchl, das Wesentlichste im Leben stets zu verfehlen, was sich hier in der Sucht und der Depression ausdr\xfcckt.",
    heilmitteltext: "<strong>Ignatia amara (Ignatiusbohne)</strong> ist das hom\xf6opathische Enneagramm-Heilmittel f\xfcr den Typ 4. Es wirkt auf der Ebene des Neid-Musters und der damit einhergehenden emotionalen Dysbalance: das Wechselhafte, das Paradoxe, die tiefe Sehnsucht nach Erf\xfcllung bei gleichzeitiger innerer Abgrenzung vom eigenen Leben. Ignatia amara wird in aufsteigenden hom\xf6opathischen Potenzen verordnet, da dieser Fall eine besonders langwierige Behandlung ben\xf6tigt. In der Enneagramm-Hom\xf6opathie steht die hohe Treffsicherheit des typspezifischen Heilmittels bei der F\xfchrung komplexer F\xe4lle klar im Vordergrund.",
    verlauf: "Langsam aber stetig reduzieren sich \xfcber Monate Menge und H\xe4ufigkeit des Alkoholkonsums. Die Depressionen werden seltener und weniger intensiv. Nach vier Monaten kann das Antidepressivum vollst\xe4ndig abgesetzt werden. Die Patientin trinkt gelegentlich noch ein bis zwei Gl\xe4ser Rotwein, wei\xdf aber, dass dies nicht der Regelfall sein sollte. Ihre Eigenwahrnehmung, sie sei \u201ePrinzessin auf der Erbse\u201c, nimmt deutlich ab. Etwa ein Jahr sp\xe4ter berichtet sie, mit ihrem Ex-Mann einen netten Abend verbracht zu haben und eine Ann\xe4herung stattgefunden h\xe4tte."
  },
  "homoeopathie-fall-5": {
    fallbeschreibung: "Ein 51-j\xe4hriger Gymnasiallehrer f\xfcr Mathematik kommt wegen starker H\xfcftschmerzen (Coxalgie). Er humpelt, war bei mehreren Orthop\xe4den und Physiotherapeuten ohne Erfolg. Der Befund lautet: Coxarthrose mit starkem Gelenkverschlei\xdf. Empfehlung der \xc4rzte: k\xfcnstliches H\xfcftgelenk. Er ist sehr frustriert, denn er hatte bis vor kurzem regelm\xe4\xdfig Sport (Volleyball und Joggen) gemacht. Im Gespr\xe4ch wirkt er distanziert, nachdenklich, objektiv und manchmal gar scheu. Er hat sich wissenschaftlich mit seinem Krankheitsbild auseinandergesetzt, sein Wissen \xfcber die Erkrankung wirkt sehr fundiert. Horizontal verlaufende Stirnfalten, ein zustimmendes Nicken und eine insgesamt emotional zur\xfckhaltende Art geben erste Hinweise auf den Typ.",
    diagnose: "Das distanzierte Auftreten, die Tendenz zur Wissensakkumulation, die horizontalen Stirnfalten als Blickqualit\xe4t, die emotionale Zur\xfcckhaltung und die Scheu vor anderen &ndash; all das sind Merkmale des <strong>Enneagrammtyps 5</strong>. Seine Grundleidenschaft ist der <strong>Geiz</strong>: Die zur\xfckhaltende, knappe Lebensenergie des F\xfcnfers schw\xe4cht auf Dauer die k\xf6rperliche Vitalit\xe4t und f\xf6rdert degenerative Prozesse in Gelenken und Geweben.",
    heilmitteltext: "<strong>Stramonium (Stechapfel)</strong> ist das hom\xf6opathische Enneagramm-Heilmittel f\xfcr den Typ 5. In der Hom\xf6opathie wirkt der Stechapfel auf die zur\xfcckgehaltene Lebensenergie und gibt dem Organismus den Impuls, Blockaden zu l\xf6sen und degenerative Entwicklungen umzukehren. Ein klassisches &bdquo;Gelenk-Heilmittel&ldquo; des Enneagramms.",
    verlauf: "Nach der Mittelgabe nehmen die H\xfcftschmerzen deutlich ab. Die Bewegungsf\xe4higkeit wird schrittweise wiederhergestellt. Binnen eines Jahres kann der Patient seine geliebten Sportarten in gem\xe4\xdfigter, altersentsprechender Form wieder aus\xfcben. Eine Operation wird auf unbestimmte Zeit verschoben. Auch der Zahnfleischbefund (Parodontose) hat sich nach ca. 3 Monaten merklich gebessert."
  },
  "homoeopathie-fall-6": {
    fallbeschreibung: "Der 53-j\xe4hrige Schulleiter an einem Gymnasium kommt auf Empfehlung des im vorigen Fall beschriebenen Patienten in die hom\xf6opathische Praxis. Er leidet unter Versagens\xe4ngsten mit zahlreichen Auswirkungen auf Denken, F\xfchlen und Handeln: starkes Schwitzen unter den Armen bei wichtigen Schulkonferenzen, Konzentrations- und Wortfindungsst\xf6rungen, vorzeitiger Samenerguss, st\xe4ndige innere Anspannung. Er \xe4rgert sich, dass er sich nicht selbstbewusst genug auftreten kann. In den letzten Jahren nehme seine \xc4ngstlichkeit zu, die innere Grenze, an der nichts mehr geht, werde immer n\xe4her. Er versucht, die Schule \xfcber immer mehr Regularien und Kontrollmechanismen zu f\xfchren.",
    diagnose: "Die Unsicherheit, die \xc4ngstlichkeit, das Misstrauen gegen\xfcber anderen Lehrern, die Tendenz zu \xfcbertriebenen Kontrollmechanismen, das konstante Gef\xfchl des Versagens trotz Funktion &ndash; das sind klar erkennbare Merkmale des <strong>Enneagrammtyps 6</strong>. Seine Grundleidenschaft ist die <strong>Angst</strong>: Diese l\xe4hmt ihn, \xe4ndert seinen K\xf6rper (Schwitzen, Sexualst\xf6rung, Konzentration) und untergr\xe4bt seine Kompetenz als F\xfchrungsperson.",
    heilmitteltext: "<strong>Opium (Schlafmohn)</strong> ist das hom\xf6opathische Enneagramm-Heilmittel f\xfcr den Typ 6. In der Hom\xf6opathie wirkt Opium auf die blockierte Kopfenergie &ndash; auf das Angst-Muster, das das klare Denken und die nat\xfcrliche Souver\xe4nit\xe4t eines Menschen l\xe4hmt. Es entsperrt die festgefrorene innere Kapazit\xe4t und gibt dem Sicherheitsorientierten seine angeborene Kompetenz zur\xfcck.",
    verlauf: "In einem Zeitraum von ca. zwei Jahren wird der Patient therapeutisch begleitet und durch das Enneagramm sensibilisiert. Er entwickelt eine bessere Eigenwahrnehmung und kann Kollegen und Sch\xfclern offener und weniger misstrauisch begegnen. Er wird deutlich gelassener. Die Spannungen im zwischenmenschlichen Bereich haben sich merklich verbessert, er wird seiner Aufgabe als Schulleiter wieder vollumf\xe4nglich gerecht. Auch das Schwitzen w\xe4hrend der Konferenzen geh\xf6rt der Vergangenheit an."
  },
  "homoeopathie-fall-7": {
    fallbeschreibung: "Eine 27-j\xe4hrige Verk\xe4uferin in einem Lebensmittel-Discounter berichtet im Erstgespr\xe4ch: Seit der Jugend leidet sie unter migr\xe4neartigen Kopfschmerzen; seit einigen Monaten zus\xe4tzlich unter schmerzhaften Gallensteinkoliken. Sie nimmt immer h\xf6here Dosen an Analgetika, die aber zunehmend weniger Wirkung zeigen. Ein MRT war unauff\xe4llig. Vor mir sitzt eine gut gelaunte, lebendige und optimistisch wirkende Frau voller Lebensfreude, die lacht, w\xe4hrend sie \xfcber ihre Symptome berichtet. Auff\xe4llig: rote Wangen, ein warmer fr\xf6hlicher Blick, entspannte Miene.",
    diagnose: "Die Lebensfreude, das warme Auftreten, der optimistische Blick trotz starker Symptome &ndash; diese Indizien f\xfcgen sich ins Bild des <strong>Enneagrammtyps 7</strong>. Seine Grundleidenschaft ist die <strong>Ma\xdflosigkeit</strong>: Das umfunktionierte Kopfzentrum der Sieben, das st\xe4ndig Positivit\xe4t generiert und Schmerz umleitet, sucht sich den Ausweg \xfcber intensive k\xf6rperliche Symptome. Migr\xe4ne und Gallensteinkoliken als zwei Seiten eines intensiven K\xf6rperausdrucks.",
    heilmitteltext: "<strong>Belladonna (Tollkirsche)</strong> ist das hom\xf6opathische Enneagramm-Heilmittel f\xfcr den Typ 7. Belladonna, klinisch bekannt f\xfcr Hitzesymptome, Pulsieren und intensive Krampfzust\xe4nde, entspricht exakt der umfunktionierten Kopfenergie des Siebeners, die sich in heftigen, pl\xf6tzlichen K\xf6rpersymptomen entl\xe4dt. Das Heilmittel wirkt auf der Essenzebene der Ma\xdflosigkeit.",
    verlauf: "Zun\xe4chst \xe4ndert sich am Gesundheitszustand wenig &ndash; eine Reaktion, die typisch f\xfcr den Heilungsverlauf der Enneagramm-Hom\xf6opathie ist. Dann aber, nach ca. vier Wochen und einer Mittelwiederholung, kommt es zu einer gro\xdfen Entspannung. Die Kopfschmerzproblematik verschwindet zusehends. Nach einer weiteren Mittelgabe treten keine Gallensteinkoliken mehr auf. Sechs Monate nach der Erstanamnese ist die Patientin in jeder Hinsicht beschwerdefrei und hat keinerlei Schmerzmittel mehr eingenommen."
  },
  "homoeopathie-fall-8": {
    fallbeschreibung: "Ein 44-j\xe4hriger Mann sucht mich auf, weil er seit ca. 10 Jahren unter manischer Depression (bipolare affektive St\xf6rung) leidet. In Maniephasen rief er seine Freunde an und teilte mit, er sei der Nachfolger Jesu Christi; in Depressionsphasen verfiel er in selbstzerst\xf6rerische Gedanken bis zum Suizidwunsch. Er hatte bereits einige l\xe4ngere Aufenthalte in psychiatrischen Kliniken. Im Gespr\xe4ch wird deutlich: Er neigt stark zur Kontrolle von Mitmenschen, agiert in Beziehungen r\u00fccksichtslos, will immer den Ton angeben. Er ist stark selbstbezogen, besitzt wenig Empathie, denkt h\xe4ufig nur an sich und seinen Vorteil. Starke k\xf6rperliche Pr\xe4senz, immense Energie, besondere energetische Intensit\xe4t.",
    diagnose: "Die \xfcberentwickelte Bauchenergie, die Dominanz, der Kontrollwunsch, die Selbstbezogenheit, die Intensit\xe4t &ndash; das sind klare Merkmale des <strong>Enneagrammtyps 8</strong>. Seine Grundleidenschaft ist die <strong>Gier (Wollust)</strong>: Die \xfcberentwickelte Bauchenergie des Achters findet keinen nat\xfcrlichen Kanal mehr, schwankt zwischen extremen Erh\xf6hungs- und Erniedrigungszust\xe4nden (Manie und Depression) und bringt das gesamte System aus dem Gleichgewicht.",
    heilmitteltext: "<strong>Veratrum album (Wei\xdfer Germer)</strong> ist das hom\xf6opathische Enneagramm-Heilmittel f\xfcr den Typ 8. Der wei\xdfe Germer entspricht hom\u00f6opathisch der \xfcbersteigerten Selbst\xfcbersch\xe4tzung (bis zur Gottgleichheit), dem Macht- und Kontrolldrang und dem explosiven K\xf6rperausdruck. Es wirkt auf der Essenzebene der Gier und bringt die extreme Pendelbewegung der bipolaren Energie zur Ruhe.",
    verlauf: "Durch die Mittelgabe sowie die intensive Besch\xe4ftigung mit dem Enneagrammtyp 8 lernt der Patient, seine sanfteren Z\xfcge zu entwickeln und eigene Verletzlichkeit zuzulassen. Er erkennt den Abwehrmechanismus der Leugnung von Schw\xe4che und beginnt, sich anzupassen. Ca. ein Jahr nach der ersten Mittelverordnung kann er seine schulmedizinischen Medikamente auf ein Minimum reduzieren. Er f\xfchlt sich lebendiger und ausgeglichener, nimmt aktiver am Leben teil. Keine weiteren Psychiatrie-Einweisungen seit Behandlungsbeginn."
  },
  "homoeopathie-fall-9": {
    fallbeschreibung: "Ein 53-j\xe4hriger Mann kommt wegen immer wiederkehrender (rezidivierender) H\xe4morrhoidalblutungen und Adipositas. Bei jedem Stuhlgang findet sich Blut in der Toilette. Eine Darmspiegelung ergab H\xe4morrhoidalleiden Stadium II sowie Fettleber. BMI 31, Adipositas Grad I. Er arbeitet sitzend bei der Arbeitsagentur, ist nach eigenen Angaben zu tr\xe4ge, um sich in der Freizeit ausreichend zu bewegen. Er ern\xe4hrt sich haupts\xe4chlich von Fertigprodukten und Fast Food, isst nach der Arbeit Unmengen an S\xfc\xdfigkeiten. Er hat einen erh\xf6hten Schlafbedarf von t\xe4glich 9\u201310 Stunden und ist seit 10 Jahren geschieden.",
    diagnose: "Die Bindung an das Physische (Essen, Schlafen, Besitz), die Passivit\xe4t, die Selbstvergessenheit, das freundlich-tr\xe4ge Wesen, das Gef\xfchl, selbst nicht geliebt zu werden, das durch Nahrungsaufnahme kompensiert wird &ndash; das sind klar erkennbare Zeichen des <strong>Enneagrammtyps 9</strong>. Seine Grundleidenschaft ist die <strong>Tr\xe4gheit</strong>: Die selbsterhaltende Tr\xe4gheit sperrt die Lebenskraft, f\xfchrt zu k\xf6rperlicher Stagnation, Gef\xe4\xdfproblemen und metabolischen Dysbalancen. Der Wunsch nach Liebe geht buchst\xe4blich in den K\xf6rper.",
    heilmitteltext: "<strong>Cannabis indica (Indischer Hanf)</strong> ist das hom\xf6opathische Enneagramm-Heilmittel f\xfcr den Typ 9. In der Hom\xf6opathie wirkt Cannabis auf genau jene tr\xe4ge, stagnative Energie, die den K\xf6rper blockiert und ihn in einem Zustand der Selbstvergessenheit h\xe4lt. Es entsperrt die Lebenskraft des Neuners und gibt dem Organismus den Impuls zur Bewegung auf allen Ebenen.",
    verlauf: "Zun\xe4chst wenig Ver\xe4nderung. Erst durch wiederholte Mittelgaben in aufsteigenden Dosierungen zeigen sich nach Monaten die ersten Zeichen der Verbesserung. Die Blutungen bleiben nach mehreren Mittelverordnungen ganz aus, die Erkrankung heilt vollst\xe4ndig. Die krankhaften H\xe4morrhoiden verschwinden dauerhaft. Nach und nach nimmt der Patient im Laufe der Monate an Gewicht ab: Von 96 kg auf 90 kg nach vier Monaten, BMI von 31 auf 29 gesunken. Er macht moderate, regelm\xe4\xdfige Spazierg\xe4nge, erkennt, dass Nahrung kein Ersatz f\xfcr Liebesgef\xfchle sein kann, und berichtet von mehr Lebensfreude und sozialen Kontakten."
  }
};

function homoeopathieFallPage(route) {
  const base = HOMOEOPATHIE_FAELLE.find(f => f.route === route);
  const detail = HOMOEOPATHIE_FALL_DETAILS[route];
  if (!base || !detail) return shell(`<div class="page-container">${pageHeader('enneagramm-homoeopathie')}<p style="padding:2rem;">Fall nicht gefunden.</p></div>`);
  return _homoeopathieFallPage(Object.assign({}, base, detail));
}

// \u2500\u2500\u2500 Enneagramm meets Reflexzonentherapie \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500

function enneagrammReflexzonentherapiePage() {
  return shell(`
    <div class="page-container">
      ${pageHeader('enneagramm-reflexzonentherapie')}
      <div class="page-content">
        <p class="eyebrow">Wissen \u00b7 K\u00f6rperarbeit</p>
        <h1 class="section-title">Enneagramm meets Reflexzonentherapie</h1>
        <h2 class="section-title" style="font-size:1.2rem;font-weight:600;margin:0 0 1.4rem;color:var(--muted);">Fu\u00df und Hand als Landkarte der drei Zentren</h2>

        <blockquote class="vb-blockquote" style="margin-bottom:1.8rem;">
          <p class="vb-intro">Die Reflexzonentherapie geht von einem einfachen, aber wirkungsvollen Prinzip aus: Auf Fu\u00dfsohle und Handinnenfl\u00e4che spiegelt sich der gesamte K\u00f6rper in verkleinerter Form wider. Jedes Organ, jede K\u00f6rperregion hat dort ihre Entsprechung \u2013 und gezielter Druck auf die passende Zone soll den zugeordneten Bereich anregen und entspannen.</p>
          <p class="vb-intro">Legt man die neun Enneagrammtypen \u00fcber diese Landkarte, entsteht eine \u00fcberraschend stimmige Parallele: Die drei Enneagramm-Zentren \u2013 Kopf, Herz und Bauch \u2013 lassen sich sowohl am Fu\u00df als auch an der Hand topografisch wiederfinden, vom Zehen- bzw. Fingerbereich \u00fcber die Mitte bis hinunter zur Ferse bzw. zum Handballen. Damit wird die Reflexzone nicht nur zu einem k\u00f6rperlichen, sondern auch zu einem psychosomatischen Kompass.</p>
        </blockquote>

        <div style="margin:0 0 2rem;border-radius:12px;overflow:hidden;box-shadow:0 2px 12px rgba(0,0,0,0.15);">
          <img src="./assets/portraits/enneagramm-reflexzonentherapie-de.jpeg" alt="\u00dcbersicht: Fu\u00df- und Handreflexzonen nach dem Enneagramm \u2013 die drei Zentren als K\u00f6rperlandkarte" style="width:100%;display:block;" loading="lazy" />
          <p style="text-align:center;font-size:0.78rem;color:var(--muted);margin:0;padding:0.5rem 0.5rem 0.7rem;">\u00dcbersicht: Die drei Zentren des Enneagramms in den Fu\u00df- und Handreflexzonen</p>
        </div>

        <div class="vb-section" style="max-width:100%;">
          <h2 style="font-size:1.1rem;font-weight:700;margin:0 0 1rem;color:var(--ink);">Teil 1: Die Fu\u00dfreflexzonen als Enneagramm-Landkarte (Die Basis &amp; das Fundament)</h2>
          <p class="vb-intro">Der Fu\u00df tr\u00e4gt uns durchs Leben \u2013 er ist unser Fundament, unser Kontakt zum Boden. Genau darin liegt die Parallele zum Enneagramm: Auch dort geht es um Grundhaltungen, auf denen der gesamte Charakter aufbaut.</p>
          <ul style="margin:0.8rem 0 1.2rem;padding-left:1.2rem;font-size:0.95rem;line-height:1.75;color:var(--ink);">
            <li><strong>Die Zehen und das Kopf-Zentrum (Typ 5, 6, 7):</strong> An den Zehen liegen die Reflexzonen f\u00fcr Kopf, Gehirn, Nebenh\u00f6hlen und Sinnesorgane \u2013 genau der K\u00f6rperbereich, in dem das Kopf-Zentrum des Enneagramms zu Hause ist: Denken, Planen, Absichern, das st\u00e4ndige Verarbeiten von Information. Verspannungen in den Zehen k\u00f6nnen auf \u00fcberreizte Kopfenergie hindeuten \u2013 zu viel gedankliches Kreisen, zu wenig Erdung im K\u00f6rper.</li>
            <li><strong>Die Fu\u00dfsohlen-Mitte und das Herz-Zentrum (Typ 2, 3, 4):</strong> Der breite Mittelbereich der Sohle deckt Herz, Lunge \u2013 aber auch Magen, Leber und Bauchspeicheldr\u00fcse ab. Das ist kein Widerspruch, sondern zeigt genau die Enneagramm-Dynamik des Herz-Zentrums: Wer sich Dinge im wahrsten Sinne \u201ezu Herzen nimmt\u201c, sp\u00fcrt das oft zuerst im Magen \u2013 lange bevor ein Thema \u201etiefer\u201c ins Bauch-Zentrum wandert.</li>
            <li><strong>Die Ferse und das Bauch-Zentrum (Typ 8, 9, 1 \u2013 das Fundament):</strong> Die Ferse tr\u00e4gt das gr\u00f6\u00dfte Gewicht und steht f\u00fcr die unteren R\u00fccken- und Beckenregionen \u2013 den k\u00f6rperlichen Ur-Grund. Das passt zum Bauch-Zentrum, das im Enneagramm ebenfalls f\u00fcr das Fundament steht: Standfestigkeit, Grenzen, das ganz basale Gef\u00fchl, im eigenen K\u00f6rper und in der Welt zu sein.</li>
          </ul>
        </div>

        <div class="vb-section" style="max-width:100%;">
          <h2 style="font-size:1.1rem;font-weight:700;margin:1.6rem 0 1rem;color:var(--ink);">Teil 2: Die Handreflexzonen als Enneagramm-Landkarte (Die feine Steuerung &amp; das Greifen)</h2>
          <p class="vb-intro">Was der Fu\u00df im Gro\u00dfen abbildet, wiederholt die Hand im Kleinen \u2013 nur feiner, differenzierter und n\u00e4her am bewussten Handeln. Die Hand ist das Werkzeug, mit dem wir aktiv in die Welt hineingreifen, gestalten und Kontakt aufnehmen.</p>
          <ul style="margin:0.8rem 0 1.2rem;padding-left:1.2rem;font-size:0.95rem;line-height:1.75;color:var(--ink);">
            <li><strong>Finger, Daumen und das Kopf-Zentrum (Typ 5, 6, 7):</strong> An Fingerkuppen und Daumen liegen die Zonen f\u00fcr Kopf und Nebenh\u00f6hlen \u2013 kleinteiliger, aber ausgepr\u00e4gter als am Fu\u00df. Passend dazu sind es gerade die Finger, mit denen wir greifen, pr\u00fcfen, begreifen: eine sehr kopfnahe, analysierende Bewegung.</li>
            <li><strong>Die Handfl\u00e4chen-Mitte und das Herz-Zentrum (Typ 2, 3, 4):</strong> Die Mitte der Handinnenfl\u00e4che entspricht Herz und Brustbereich \u2013 nicht zuf\u00e4llig legen wir die Hand instinktiv genau dorthin, wenn wir etwas ans Herz nehmen oder tr\u00f6sten wollen. Die Hand als Ausdrucksorgan des Herz-Zentrums: Ber\u00fchrung, Zuwendung, das Reichen der Hand als Geste der Beziehung.</li>
            <li><strong>Handballen, Handwurzel und das Bauch-Zentrum (Typ 8, 9, 1):</strong> Der untere, kr\u00e4ftige Teil der Hand \u2013 Handballen und Handwurzel \u2013 steht f\u00fcr die unteren R\u00fccken- und Beckenzonen. Genau dieser Bereich \u00fcbt beim Zupacken den meisten Druck aus: die K\u00f6rperkraft des Bauch-Zentrums, sp\u00fcrbar bis in die Hand hinein.</li>
          </ul>
        </div>

        <div class="vb-section" style="max-width:100%;">
          <h2 style="font-size:1.1rem;font-weight:700;margin:1.6rem 0 1rem;color:var(--ink);">Zusammenfassender Blick und n\u00e4chster Schritt</h2>
          <p class="vb-intro">Fu\u00df und Hand erz\u00e4hlen also dieselbe Geschichte auf zwei verschiedenen Ebenen: der Fu\u00df als gro\u00dfe, tragende Basis-Landkarte des ganzen K\u00f6rpers, die Hand als feineres, aktiveres Abbild derselben drei Zentren. Wer die eigene Reflexzonen-Massage bewusst mit dem eigenen Enneagrammtyp verkn\u00fcpft, kann dabei ganz nebenbei sp\u00fcren, in welchem Zentrum gerade die meiste Spannung sitzt \u2013 ein kleiner, k\u00f6rperlicher Realit\u00e4tscheck f\u00fcr das eigene Grundmuster.</p>
          <p class="vb-intro" style="margin-bottom:0;">Wer die praktische Umsetzung sucht \u2013 mit Igelball, Kork- oder Holzroller, konkreten Handgriffen f\u00fcr Fu\u00df und Hand \u2013 findet die Anleitung dazu bei den Praxistipps vom Heilpraktiker: <a href="javascript:void(0)" data-route="praxistipps-heilpraktiker/fussreflexzonen-aktivierung" style="color:var(--copper);text-decoration:underline;">Fu\u00dfreflexzonen-Aktivierung</a>.</p>
        </div>

        ${bookTip("hinter-der-leidenschaft", "Die neun Wunden des Enneagramms \u2013 tiefgreifende Analyse der Urwunde hinter jeder Leidenschaft, mit konkreten Heilungswegen f\u00fcr alle 9 Typen.", "Hinter der Leidenschaft")}
        ${bookTip("leidenschaft-und-heilung", "27 Subtypen \u2013 Leidenschaften, Tugenden und Heilungswege direkt aus der therapeutischen Praxis.", "Leidenschaft und Heilung")}
        ${bookTip("heilung-als-erinnerung", "Heilung nicht als Reparatur, sondern als Erinnerung an das, was wir eigentlich sind \u2013 ein tiefgr\u00fcndiger Blick auf Gesundheit und Ganzheit.", "Heilung als Erinnerung")}
        ${relatedLinks([
          {route:"enneagramm-homoeopathie", label:"Enneagramm meets Hom\u00f6opathie"},
          {route:"enneagramm-handanalyse", label:"Enneagramm meets Handanalyse"},
          {route:"enneagramm-zahnpsychosomatik", label:"Enneagramm meets Zahn-Psychosomatik"},
          {route:"praxistipps-heilpraktiker/fussreflexzonen-aktivierung", label:"Praxistipp: Fu\u00dfreflexzonen-Aktivierung"},
          {route:"drei-zentren", label:"Schaubild: Drei Zentren"},
        ])}
      </div>
    </div>
  `);
}

// \u2500\u2500\u2500 Enneagramm meets Zahn-Psychosomatik \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500

function enneagrammZahnpsychosomatikPage() {
  return shell(`
    <div class="page-container">
      ${pageHeader('enneagramm-zahnpsychosomatik')}
      <div class="page-content">
        <p class="eyebrow">Wissen \u00b7 Psychosomatik</p>
        <h1 class="section-title">Die dynamische Verbindung von Zahn-Psychosomatik und Enneagramm</h1>
        <h2 class="section-title" style="font-size:1.2rem;font-weight:600;margin:0 0 1.4rem;color:var(--muted);">Die Architektur der Seele im Kiefer: Warum das dynamische Enneagramm und die Zahn-Psychosomatik Hand in Hand gehen</h2>

        <blockquote class="vb-blockquote" style="margin-bottom:1.8rem;">
          <p class="vb-intro">In der ganzheitlichen Betrachtung des Menschen suchen wir oft nach klaren Schubladen: Welcher Zahn geh\u00f6rt zu welchem Organ? Welches Enneagramm-Muster entspricht welcher K\u00f6rperspannung? Doch wer den Menschen auf diese Weise starr einteilt, \u00fcbersieht das Wesentliche. Die Psyche ist kein statisches Monument, und der K\u00f6rper erst recht nicht. Das Enneagramm ist ein System der st\u00e4ndigen Bewegung, des Flie\u00dfens und der inneren Alchemie.</p>
          <p class="vb-intro">Dennoch brauchen wir f\u00fcr den Einstieg eine Orientierung, eine Grundstruktur. Das Geheimnis liegt darin, diese klare Basisstruktur als Ausgangspunkt zu begreifen, um sie im n\u00e4chsten Schritt als ein dynamisches, lebendiges Gef\u00fcge zu verstehen. Es ist wie bei einer Landkarte: Die Linien sind starr, aber das Leben, das sich auf ihr abspielt, ist voller Fluss, Richtungswechsel und \u00dcberlappungen.</p>
        </blockquote>

        <div style="margin:0 0 2rem;border-radius:12px;overflow:hidden;box-shadow:0 2px 12px rgba(0,0,0,0.15);">
          <img src="./assets/portraits/enneagramm-zahnpsychosomatik-de.jpeg" alt="\u00dcbersicht: Enneagramm und Zahn-Psychosomatik \u2013 Zentren und Zahngruppen" style="width:100%;display:block;" loading="lazy" />
          <p style="text-align:center;font-size:0.78rem;color:var(--muted);margin:0;padding:0.5rem 0.5rem 0.7rem;">\u00dcbersicht: Die drei Zentren des Enneagramms und ihre Entsprechung in den drei Zahngruppen</p>
        </div>

        <div class="vb-section" style="max-width:100%;">
          <h2 style="font-size:1.1rem;font-weight:700;margin:0 0 1rem;color:var(--ink);">1. Das Fundament: Die klare Basisstruktur als erster Anker</h2>
          <p class="vb-intro">Um die Verbindung zwischen Z\u00e4hnen und Enneagramm \u00fcberhaupt greifbar zu machen, dient die klassische Zuordnung der Zentren und Zahngruppen als wertvolles Orientierungsraster. Sie gibt dem Leser den roten Faden an die Hand:</p>
          <ul style="margin:0.8rem 0 1.2rem;padding-left:1.2rem;font-size:0.95rem;line-height:1.75;color:var(--ink);">
            <li><strong>Das Kopf-Zentrum (Typ 5, 6, 7) und die Schneidez\u00e4hne:</strong> Sie stehen f\u00fcr das Wasser-Element, die Nieren und die Ur-Angst. Die Frontz\u00e4hne bilden unsere Visitenkarte, unser Selbstbild und die Frage nach der eigenen Identit\u00e4t in einer unsicheren Welt.</li>
            <li><strong>Das Bauch-Zentrum (Typ 8, 9, 1) und die Eckz\u00e4hne:</strong> Sie repr\u00e4sentieren das Holz-Element, Leber/Galle und die rohe Instinktkraft. Die Eckz\u00e4hne sind die Waffen des Willens, mit denen wir uns Raum verschaffen, Grenzen setzen und mit unterdr\u00fcckter oder gelebter Wut umgehen.</li>
            <li><strong>Das Herz-Zentrum (Typ 2, 3, 4) und die Backenz\u00e4hne:</strong> Sie sind die schweren Mahlwerkzeuge f\u00fcr die Alltagsbew\u00e4ltigung. Sie tragen die Lasten, das Funktionieren, den Leistungsdruck und den emotionalen Preis, den wir f\u00fcr Anerkennung und Liebe zahlen.</li>
          </ul>
          <p class="vb-intro">Diese Struktur bietet eine wunderbare erste \u00dcbersicht. Sie zeigt, wie die drei gro\u00dfen menschlichen Grundthemen \u2013 Angst im Kopf, Wut im Bauch, Scham/Gef\u00fchl im Herzen \u2013 mechanisch und energetisch in unseren Kiefer eingeschrieben sind.</p>
        </div>

        <div class="vb-section" style="max-width:100%;">
          <h2 style="font-size:1.1rem;font-weight:700;margin:1.6rem 0 1rem;color:var(--ink);">2. Der Blick hinter die Kulissen: Warum das System in der Realit\u00e4t flie\u00dft</h2>
          <p class="vb-intro">Wer sich intensiver mit dem Enneagramm und der Psychosomatik besch\u00e4ftigt, merkt jedoch schnell, dass die Realit\u00e4t komplexer ist. Menschen sind keine reinen Lehrbuchbeispiele ihres Haupttyps. Das Enneagramm lebt von Dynamiken:</p>
          <ul style="margin:0.8rem 0 1.2rem;padding-left:1.2rem;font-size:0.95rem;line-height:1.75;color:var(--ink);">
            <li><strong>Die Fl\u00fcgel (Wings):</strong> Z. B. ist ein Typ 4 zwar im Herzzentrum zu Hause, hat aber fast immer Einfl\u00fcsse seiner Nachbartypen (3 oder 5).</li>
            <li><strong>Stress- und Wachstumsrichtung (Pfeile):</strong> Wir wandern unter Druck in andere Typen hinein und nehmen deren k\u00f6rperliche und mentale Spannungszust\u00e4nde an.</li>
            <li><strong>Die Schatten und Kernemotionen:</strong> Eine Emotion wie Scham (klassisch beim Typ 4) ist eng mit Ur-\u00c4ngsten und Schutzmechanismen verschmolzen.</li>
          </ul>

          <h3 style="font-size:1rem;font-weight:700;margin:1.4rem 0 0.8rem;color:var(--ink);">Das Fallbeispiel: Warum die Vier pl\u00f6tzlich an den Schneidez\u00e4hnen leidet</h3>
          <p class="vb-intro">Um diese Dynamik greifbar zu machen, kehren wir zu dem zuvor genannten Beispiel zur\u00fcck: Ein Typ 4 (Der Individualist) geh\u00f6rt dem Herzzentrum an, leidet aber unter massiven Problemen an den Schneidez\u00e4hnen.</p>
          <ul style="margin:0.8rem 0 1.2rem;padding-left:1.2rem;font-size:0.95rem;line-height:1.75;color:var(--ink);">
            <li>Der starre Blick w\u00fcrde sagen: \u201eDas passt nicht, Schneidez\u00e4hne geh\u00f6ren zum Kopf-Zentrum und zur Angst."</li>
            <li>Der dynamische Blick erkennt das wahre Drama dahinter: Die Kernemotion der Vier ist die Scham \u2013 das tiefe Gef\u00fchl, grundlegend fehlerhaft oder \u201eanders" zu sein. Scham ist aber nichts anderes als die pure Angst vor Entbl\u00f6\u00dfung, vor Ablehnung und davor, als unvollkommen gesehen zu werden. Ber\u00fchrt diese Scham den 5er-Fl\u00fcgel der Vier (der ohnehin dazu neigt, sich intellektuell aus der Welt zur\u00fcckzuziehen und \u00e4ngstlich zu beobachten), zieht sich der Mensch komplett in den Kopf zur\u00fcck.</li>
            <li>Das Resultat: Der Schmerz der Scham bricht genau dort durch, wo wir nach au\u00dfen hin sichtbar sind \u2013 an den Schneidez\u00e4hnen. Der K\u00f6rper l\u00fcgt nicht. Er zeigt nicht das starre Etikett des Enneagrammtyps, sondern die aktive emotionale Verschiebung im System.</li>
          </ul>
        </div>

        <div class="vb-section" style="max-width:100%;">
          <h2 style="font-size:1.1rem;font-weight:700;margin:1.6rem 0 1rem;color:var(--ink);">3. Orientierung f\u00fcr den Leser: Wie man die Zeichen im Kiefer liest</h2>
          <p class="vb-intro">Um diese feine Struktur richtig zu deuten, braucht es ein tieferes Verst\u00e4ndnis. Man muss sich auf eine kleine Entdeckungsreise einlassen:</p>
          <ol style="margin:0.8rem 0 1.2rem;padding-left:1.2rem;font-size:0.95rem;line-height:1.75;color:var(--ink);">
            <li><strong>Die Orientierung nutzen:</strong> Nimm die klassische Dreiteilung (Schneidez\u00e4hne = Identit\u00e4t/Kopf, Eckz\u00e4hne = Wille/Bauch, Backenz\u00e4hne = Lasten/Herz) als deine erste Kompassnadel. Sie hilft dir zu verstehen, wo im K\u00f6rper welcher Grundkonflikt prim\u00e4r parkt.</li>
            <li><strong>Die Dynamik zulassen:</strong> Erlaube dir den Blick f\u00fcr die Zwischent\u00f6ne. Wenn dein Schmerz oder dein Knirschen nicht \u201eins Schema" passt, frage dich: Welcher Fl\u00fcgel ist gerade aktiv? In welches Stressmuster bin ich abgerutscht? Welche versteckte Emotion (wie Scham unter der Vier oder Angst hinter der harten Fassade der Acht) dr\u00fcckt hier gerade auf den Nerv?</li>
            <li><strong>Den K\u00f6rper als Verb\u00fcndeten sehen:</strong> Z\u00e4hne sind wie ein Seismograf. Sie registrieren Beben, lange bevor wir sie kognitiv begreifen. Wer sich intensiv mit diesem Zusammenspiel besch\u00e4ftigt, erkennt, dass jede Zahnspannung eine Einladung zur Bewusstwerdung ist.</li>
          </ol>
          <p class="vb-intro" style="margin-bottom:0;">Die Struktur ist also da \u2013 wie ein stabiles Skelett. Aber erst das Verst\u00e4ndnis f\u00fcr die Dynamik und die flie\u00dfenden \u00dcberg\u00e4nge haucht ihr das Leben ein, das den wahren Menschen in all seiner Komplexit\u00e4t widerspiegelt.</p>
        </div>

        ${bookTip("hinter-der-leidenschaft", "Die neun Wunden des Enneagramms \u2013 tiefgreifende Analyse der Urwunde hinter jeder Leidenschaft, mit konkreten Heilungswegen f\u00fcr alle 9 Typen.", "Hinter der Leidenschaft")}
        ${bookTip("leidenschaft-und-heilung", "27 Subtypen \u2013 Leidenschaften, Tugenden und Heilungswege direkt aus der therapeutischen Praxis.", "Leidenschaft und Heilung")}
        ${bookTip("heilung-als-erinnerung", "Heilung nicht als Reparatur, sondern als Erinnerung an das, was wir eigentlich sind \u2013 ein tiefgr\u00fcndiger Blick auf Gesundheit und Ganzheit.", "Heilung als Erinnerung")}
        ${relatedLinks([
          {route:"enneagramm-homoeopathie", label:"Enneagramm meets Hom\u00f6opathie"},
          {route:"enneagramm-reflexzonentherapie", label:"Enneagramm meets Reflexzonentherapie"},
          {route:"drei-zentren", label:"Schaubild: Drei Zentren"},
          {route:"wunden", label:"Die 9 Wunden der Enneagrammtypen"},
          {route:"basisemotionen", label:"Schaubild: Basisemotionen"},
        ])}
      </div>
    </div>
  `);
}
// ─── Enneagramm meets Handanalyse ──────────────────────────────────────────

function enneagrammHandanalysePage() {
  const HAND_ZENTREN = [
    {
      zentrum: "Das Kopf-Zentrum (Typ 5, 6, 7): Die Welt des Intellekts und der „Luft-Hand“",
      intro: "Menschen aus dem Kopf-Zentrum leben im Verstand. Ihre Hände gehören meist zum Typ der Luft-Hand: eine eher quadratische oder rechteckige Handfläche mit auffallend langen, schlanken Fingern und klaren Gelenken. Die Finger haben oft spürbare Abstände zueinander – ein unbewusstes Zeichen für den Wunsch nach mentalem Freiraum und Distanz.",
      typen: [
        { typ: 5, titel: "Der Beobachter – Die distanzierte Analyse-Hand", punkte: [
          "Die Hand der Fünf wirkt oft kühler, sehnig und schlank, fast so, als hätte sie nichts Überflüssiges an sich. Zwischen den Fingern – besonders zwischen Mittel- und Ringfinger – fällt häufig ein deutlicher Abstand auf, und wer genau hinsieht, erkennt darin eine körperliche Übersetzung der inneren Grenzziehung: ›Ich trete einen Schritt zurück und beobachte.‹ Nichts an dieser Hand drängt sich auf, alles hält Distanz.",
          "In der Handfläche verläuft die Kopflinie – jene mittlere Linie, die quer über die Hand zieht – bei der Fünf oft extrem tief geschnitten, schnurgerade und deutlich abgesetzt von der Lebenslinie. Diese räumliche Trennung der beiden Linien ist mehr als ein optisches Detail: Sie erzählt von einer Person, die Denken und Leben bewusst auseinanderhält, die sich lieber zurückzieht, um in Ruhe zu verarbeiten, statt sich ungefiltert ins Geschehen zu werfen.",
          "Dahinter steckt die Seele der Fünf: ein tiefes Bedürfnis nach geistigem Autonomie-Bereich, nach einem Ort, an dem niemand ungefragt eindringt. Die Hand spiegelt genau diesen Wunsch – das Leben lieber mit dem Kopf zu greifen, es zu verstehen und einzuordnen, statt sich emotional kopfüber hineinzuwerfen.",
        ]},
        { typ: 6, titel: "Der Loyale – Die verlässliche Anker-Hand", punkte: [
          "Die Sechs zeigt sich in einer soliden, ausgeglichenen Handform mit festen, aber nicht starren Fingern. Der Daumen steht stabil und schmiegt sich nicht flach an die Handfläche an – er behauptet seinen eigenen Raum, ohne aufdringlich zu wirken. Die Finger selbst stehen in einem harmonischen, gleichmäßigen Abstand zueinander: weder so weit auseinander, dass daraus Isolation spricht, noch so eng, dass sich ein Klammern andeutet.",
          "Bei der sicherheitsorientierten Sechs findet sich in der Handmitte häufig eine sehr gerade, gut sichtbare Schicksalslinie – jene senkrechte Linie, die sich klar durch die Handfläche zieht. Sie liest sich fast wie ein roter Faden, der Stabilität verspricht und einen klar erkennbaren Lebenspfad andeutet, selbst wenn die Sechs selbst innerlich oft zwischen Zweifel und Zuversicht schwankt.",
          "Diese Hand strahlt vor allem eines aus: Verlässlichkeit. Die Sechs sucht Halt in Struktur und Loyalität, und genau das zeigt sich in der festen, zugleich flexiblen Bauart ihrer Hand – stabil genug, um Sicherheit zu geben, beweglich genug, um sich nicht zu verkrampfen.",
        ]},
        { typ: 7, titel: "Der Enthusiast – Die dynamische Entdecker-Hand", punkte: [
          "Bei der Sieben fällt zuerst die Beweglichkeit auf: eine flexible Hand mit leicht biegsamen Fingern und Gelenken, die fast so wirken, als würden sie gleichzeitig nach allen Seiten greifen wollen. Die Abstände zwischen den Fingern sind dynamisch statt starr, und der kleine Finger steht oft leicht abgespreizt – ein körperliches Echo von Neugier und dem beständigen Drang nach Kommunikation.",
          "Die Lebenslinie, jener große Bogen, der sich um den Daumenballen zieht, verläuft bei der Sieben häufig weit geschwungen und bricht manchmal sogar nach außen hin aus – als suche sie sich abseits der gewohnten Bahn ihren eigenen Weg. Genau dieser Ausbruch signalisiert Bewegungsdrang und Experimentierfreude, das Gegenteil eines eng gezogenen, vorhersehbaren Pfades.",
          "Die Sieben will das Leben in vollen Zügen kosten, und ihre Hände sind selten wirklich still. Sie sind ständig in Bewegung, symbolisieren spielerische Leichtigkeit und den steten Drang, ja nichts zu verpassen, das das Leben noch zu bieten hat.",
        ]},
      ]
    },
    {
      zentrum: "Das Bauch-Zentrum (Typ 8, 9, 1): Instinkt, Erdung und die „Erde-Hand“",
      intro: "Das instinktgetriebene Bauch-Zentrum ringt mit Präsenz, Kontrolle und innerem Frieden. Ihre Hände sind meist kräftige Erde- oder Feuer-Hände: breite Handflächen, dickere Knöchel und festere, kürzere Finger, die fest in der Materie stehen.",
      typen: [
        { typ: 8, titel: "Der Herausforderer – Die entschlossene Macht-Hand", punkte: [
          "Die Acht besitzt eine breite, massive Handfläche mit einem sehr kräftigen, muskulösen Daumenballen – dem sogenannten Thenar. Die Finger selbst sind kurz, stämmig und stehen entschlossen beieinander, als würden sie keinen Zweifel an ihrer Zusammengehörigkeit dulden. Auffällig ist der Daumen: Er steht kraftvoll und weit von der Hand abgespreizt, fast wie ein eigener kleiner Willensbeweis.",
          "In dieser Hand sind alle Hauptlinien – Lebenslinie, Kopf- und Herzlinie – tief, kräftig und oft rot eingefärbt zu erkennen. Feine Ziselierungen, zarte Verzweigungen oder zögerliche Unterbrechungen sucht man hier vergeblich – stattdessen herrscht pure Direktheit, eine Hand ohne Umwege.",
          "Die Acht beansprucht Raum für sich, und genau das spiegeln der dominante Daumen und die breite Handfläche wider: unerschütterliche Willenskraft, ein instinktiver Schutzreflex für die eigenen Leute und eine natürliche Führungskraft, die keine großen Worte braucht.",
        ]},
        { typ: 9, titel: "Der Vermittler – Die sanfte Friedens-Hand", punkte: [
          "Bei der Neun überwiegen weiche, runde Handformen, bei denen die Finger nahtlos und sanft in die Handfläche übergehen – ohne harte Kanten, ohne scharfe Übergänge. Die Finger selbst liegen oft dicht beieinander, wie zu einer Einheit verschmolzen, statt sich einzeln voneinander abzugrenzen.",
          "Auch die Linien wirken bei der Neun oft etwas verschwommen, weich und harmonisch – nichts drängt sich scharfkantig in den Vordergrund. Die Herzlinie verläuft dabei meist sanft und gerade quer über die Handfläche, ohne dramatische Brüche oder plötzliche Richtungswechsel.",
          "Die Neun sehnt sich nach Seelenfrieden und dem Ausgleich von Spannungen, und genau diese weiche Handform ist ihr körperlicher Ausdruck: das unbewusste Vermeiden von Konflikten, gepaart mit einer tiefen, fast mütterlich-väterlichen Sanftmut, die andere zur Ruhe kommen lässt.",
        ]},
        { typ: 1, titel: "Der Perfektionist – Die geordnete Struktur-Hand", punkte: [
          "Die Hand der Eins wirkt sehr aufgeräumt, fast symmetrisch. Die Finger sind gerade, präzise geformt und stehen in exakten, gleichmäßigen Abständen zueinander – nichts wirkt hier „wild“ oder ausgefranst, jedes Detail scheint an seinem vorgesehenen Platz zu sitzen.",
          "Kopflinie und Herzlinie laufen bei der Eins auffällig parallel und gerade, sauber geschnitten, fast so, als wären sie mit dem Lineal gezogen worden. Diese Ordnung im Kleinen ist kein Zufall, sondern das genaue Gegenstück zu jener inneren Stimme, die ständig Fehler und Unstimmigkeiten sucht.",
          "Die Eins liebt Ordnung und Prinzipien, und eine Hand, bei der jede Linie logisch und exakt verläuft, beruhigt genau diesen inneren Kritiker. Sie schenkt das Gefühl von absoluter Kontrolle und einer stillen, fast klassizistischen Ästhetik.",
        ]},
      ]
    },
    {
      zentrum: "Das Herz-Zentrum (Typ 2, 3, 4): Emotion, Bühne und die „Wasser-Hand“",
      intro: "Im Herzzentrum dreht sich alles um Image, Beziehungen und tiefe Gefühlswelten. Ihre Hände entsprechen dem Typ der Wasser-Hand: oval, feingliedrig, mit geschmeidigen, weichen Gelenken und einer besonderen Betonung der Herzlinie – jener obersten der drei großen Hauptlinien, die am Rand der Hand unter dem kleinen Finger beginnt und quer über die Handfläche in Richtung des Raumes zwischen Zeige- und Mittelfinger verläuft. Sie gilt als das absolute Barometer für unsere emotionale Welt, Empathie und Beziehungsfähigkeit.",
      typen: [
        { typ: 2, titel: "Der Helfer – Die warme Herz-Hand", punkte: [
          "Die Zwei besitzt weiche, biegsame Hände, bei denen die Finger offen und einladend zueinander stehen – als würden sie sich instinktiv nach außen öffnen, statt sich abzuschotten.",
          "Der eigentliche Star dieser Hand ist ihre Herzlinie: lang, tief geschwungen, und am Ende deutlich nach oben gebogen – direkt zum Bereich zwischen Zeige- und Mittelfinger, manchmal sogar bis zum Zeigefinger hin.",
          "In der Handlesekunst zeigt eine solche, nach oben steigende Herzlinie eine enorme emotionale Hingabefähigkeit und Wärme an, dazu das tiefe Bedürfnis, geliebt zu werden und für andere da zu sein – die zentrale Melodie der Zwei, sichtbar bis in die Handfläche hinein.",
        ]},
        { typ: 3, titel: "Der Erfolgreiche – Die repräsentative Erfolgshand", punkte: [
          "Bei der Drei begegnen einem makellose, gepflegte Hände mit wohlproportionierten Fingern und Fingernägeln, die oft sehr bewusst eingesetzt werden – die Hand als Teil der äußeren Erscheinung, nicht nur als Werkzeug.",
          "Die Linien selbst sind klar, unauffällig und sauber gezeichnet: keine tiefen, dramatischen Furchen, sondern ein feines, klares Netz, das Effizienz und Kontrolle signalisiert statt innerer Turbulenz.",
          "Die Drei will glänzen und legt Wert auf Status, und genau so wirken ihre Hände: wie ein „Visitenkarten-Objekt“, dynamisch, zielgerichtet und stets bereit, zur erfolgreichen geschäftlichen oder gesellschaftlichen Begrüßung gereicht zu werden.",
        ]},
        { typ: 4, titel: "Der Individualist – Die expressive Tiefen-Hand", punkte: [
          "Die Vier zeigt sich in langen, sehr expressiven Händen mit oft leicht unregelmäßigen, kreativen Fingern, deren Haut mitunter zart und dünn wirkt – fast so, als läge das Innenleben näher an der Oberfläche als bei anderen Typen.",
          "Die Herzlinie ist bei der Vier oft extrem tief geschnitten, manchmal wellenförmig oder von feinen Nebenlinien durchzogen – ein Ausdruck emotionaler Turbulenz und Melancholie. In seltenen Fällen findet sich hier sogar eine sogenannte Simian-Linie, eine einzige, durchgehende Quernaht, bei der Herz- und Kopflinie zu einer Linie verschmelzen: ein klassisches Zeichen für extreme Intensität, für das Gefühl, „anders“ zu sein, und für eine tiefe, unbändige Gefühlswelt.",
          "Die Vier sucht das Einzigartige und Kunstvolle, und ihre Hand spiegelt genau dieses innere Drama wider: die schöpferische Tiefe und die Sehnsucht nach authentischem Ausdruck, die sich nicht mit einer glatten Oberfläche zufriedengibt.",
        ]},
      ]
    },
  ];

  function handBlock(t) {
    const col = (typeof TYPE_COLORS !== 'undefined' ? TYPE_COLORS[t.typ] : null) || 'var(--copper)';
    return `<div style="border-left:3px solid ${col};padding-left:1.1rem;margin-bottom:1.2rem;">
      <div style="font-size:0.72rem;font-weight:700;letter-spacing:0.1em;text-transform:uppercase;color:${col};margin-bottom:0.4rem;">Typ ${t.typ}</div>
      <h3 style="font-size:1.02rem;font-weight:700;margin:0 0 0.6rem;color:${col};">${t.titel}</h3>
      ${t.punkte.map(p => `<p class="vb-intro" style="margin-bottom:0.7rem;">${p}</p>`).join('')}
    </div>`;
  }

  function handZentrumBlock(z, i) {
    return `<div class="vb-section" style="max-width:100%;margin-top:${i === 0 ? '0' : '2rem'};">
      <h2 style="font-size:1.1rem;font-weight:700;margin:0 0 0.8rem;color:var(--ink);">${i + 1}. ${z.zentrum}</h2>
      <p class="vb-intro" style="margin-bottom:1.2rem;">${z.intro}</p>
      ${z.typen.map(handBlock).join('')}
    </div>`;
  }

  return shell(`
    <div class="page-container">
      ${pageHeader('enneagramm-handanalyse')}
      <div class="page-content">
        <p class="eyebrow">Wissen · Körperarbeit</p>
        <h1 class="section-title">Enneagramm meets Handanalyse</h1>
        <h2 class="section-title" style="font-size:1.2rem;font-weight:600;margin:0 0 1.4rem;color:var(--muted);">Hand und Seele: Die 9 Enneagrammtypen im Spiegel der Handanalyse</h2>

        <blockquote class="vb-blockquote" style="margin-bottom:1.8rem;">
          <p class="vb-intro">Jede Hand erzählt eine Geschichte. Während die Form unserer Hände und die Abstände unserer Finger unseren angeborenen Wesenskern widerspiegeln, zeigen uns die Handlinien – insbesondere die Herzlinie –, wie wir fühlen, lieben und mit inneren Konflikten umgehen.</p>
          <p class="vb-intro">Zwei verwandte, aber unterschiedliche Traditionen beschäftigen sich seit Jahrhunderten mit diesem Thema: die <strong>Handanalyse (Chirologie)</strong>, die Handform, Fingerabstände und Linienverlauf eher psychologisch-charakterkundlich deutet, und die <strong>Chiromantie</strong> – die klassische Handlesekunst im engeren Sinne, die zusätzlich stark wahrsagerisch-hellseherisch geprägt ist und traditionell auch Aussagen über die Zukunft treffen will. Beide Stränge gehören zum selben alten Wissensschatz über die Sprache der Hand, und beide dienen hier gemeinsam als Inspirationsquelle – nicht als exakte Wissenschaft, sondern als ein weiterer poetischer Spiegel, durch den sich die neun Enneagrammtypen betrachten lassen.</p>
          <p class="vb-intro" style="margin-bottom:0;">Verknüpfen wir dieses alte Wissen der Handlesekunst mit dem tiefenpsychologischen Enneagramm, entsteht ein faszinierendes Porträt unserer Persönlichkeit – von der distanzierten Analyse-Hand der Fünf bis zur dramatischen Tiefen-Hand der Vier.</p>
        </blockquote>

        <div style="margin:0 0 2rem;border-radius:12px;overflow:hidden;box-shadow:0 2px 12px rgba(0,0,0,0.15);">
          <img src="./assets/portraits/enneagramm-handanalyse-de.jpeg" alt="Übersicht: Enneagramm und Handanalyse – die drei Zentren im Spiegel von Handform und Handlinien" style="width:100%;display:block;" loading="lazy" />
          <p style="text-align:center;font-size:0.78rem;color:var(--muted);margin:0;padding:0.5rem 0.5rem 0.7rem;">Von der kühlen Analyse-Hand der Fünf bis zur dramatischen Tiefen-Hand der Vier: Neun Handtypen als Spiegelbild der neun Enneagrammtypen.</p>
        </div>

        <div style="margin:0 0 1.4rem;border-radius:12px;overflow:hidden;box-shadow:0 2px 12px rgba(0,0,0,0.15);">
          <img src="./assets/portraits/enneagramm-handlinien-chiromantie.jpeg" alt="Die wichtigsten Handlinien der Chiromantie: Herzlinie, Kopflinie, Lebenslinie und Schicksalslinie im Überblick" style="width:100%;display:block;" loading="lazy" />
        </div>

        <div class="vb-section" style="max-width:100%;margin-bottom:2rem;">
          <h2 style="font-size:1.1rem;font-weight:700;margin:0 0 0.8rem;color:var(--ink);">Die Handlinien im Überblick</h2>
          <p class="vb-intro" style="margin-bottom:1.2rem;">Bevor es in die einzelnen Handtypen geht, hier die vier Linien, auf die im Text immer wieder Bezug genommen wird. Nicht jede Linie ist bei jeder Hand gleich deutlich ausgeprägt – das gehört zur Individualität jeder einzelnen Hand dazu.</p>
          <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem;">
            <div style="background:var(--ivory);border:1px solid var(--border);border-radius:12px;padding:1rem 1.2rem;border-left:4px solid #7a9e5a;">
              <strong style="display:block;margin-bottom:0.4rem;color:var(--ink);">Lebenslinie</strong>
              <p style="font-size:0.88rem;line-height:1.6;color:var(--muted);margin:0;">Der große Bogen, der sich um den Daumenballen (das sogenannte Thenar) zieht. Sie steht für Vitalität und Lebenskraft, für die Art, wie jemand sich durchs Leben bewegt – entgegen einem verbreiteten Irrglauben sagt sie nichts über die Lebensdauer aus.</p>
            </div>
            <div style="background:var(--ivory);border:1px solid var(--border);border-radius:12px;padding:1rem 1.2rem;border-left:4px solid #4a6e9e;">
              <strong style="display:block;margin-bottom:0.4rem;color:var(--ink);">Kopflinie</strong>
              <p style="font-size:0.88rem;line-height:1.6;color:var(--muted);margin:0;">Die mittlere der drei Hauptlinien, sie verläuft quer über die Handfläche. Sie gibt Auskunft über Denkweise und Konzentrationsfähigkeit – ob eher gerade und fokussiert oder geschwungen und assoziativ.</p>
            </div>
            <div style="background:var(--ivory);border:1px solid var(--border);border-radius:12px;padding:1rem 1.2rem;border-left:4px solid #9e4a5a;">
              <strong style="display:block;margin-bottom:0.4rem;color:var(--ink);">Herzlinie</strong>
              <p style="font-size:0.88rem;line-height:1.6;color:var(--muted);margin:0;">Die oberste der drei Hauptlinien, sie beginnt am Handrand unter dem kleinen Finger. Sie gilt als das Barometer für Gefühlsleben, Empathie und Beziehungsfähigkeit – ihr Verlauf wird als Ausdruck emotionaler Offenheit gedeutet.</p>
            </div>
            <div style="background:var(--ivory);border:1px solid var(--border);border-radius:12px;padding:1rem 1.2rem;border-left:4px solid #8a7a4a;">
              <strong style="display:block;margin-bottom:0.4rem;color:var(--ink);">Schicksalslinie</strong>
              <p style="font-size:0.88rem;line-height:1.6;color:var(--muted);margin:0;">Die senkrechte Linie, die von der Handwurzel in Richtung Mittelfinger zieht – nicht bei jeder Hand gleich klar erkennbar. Sinnbildlich steht sie für Lebensrichtung, äußere Einflüsse und das Gefühl, einem erkennbaren Weg zu folgen. In der Chiromantie auch Saturnlinie genannt: Bei jüngeren Menschen ist sie oft noch schwächer ausgeprägt, unterbrochen oder ganz unsichtbar, weil sich der berufliche und lebensbestimmende Weg erst noch findet. Während die Hauptlinien wie Herz- und Kopflinie meist schon bei der Geburt klar angelegt sind, entsteht die Schicksalslinie erst nach und nach durch Handbeanspruchung, Gewohnheiten und gelebte Entscheidungen – und gräbt sich mit zunehmender Lebenserfahrung tiefer ein, je mehr sich der eigene Weg verfestigt.</p>
            </div>
          </div>
        </div>

        ${HAND_ZENTREN.map(handZentrumBlock).join('')}

        <div class="vb-section" style="max-width:100%;margin-top:2rem;">
          <h2 style="font-size:1.1rem;font-weight:700;margin:0 0 0.8rem;color:var(--ink);">Fazit: Die Hand als stiller Erzähler</h2>
          <p class="vb-intro">Ob die weit gestellten Finger der beobachtenden Fünf, der kraftvolle Daumen der herausfordernden Acht oder die sanft nach oben schwingende Herzlinie der helfenden Zwei – unsere Hände sind mehr als reine Greifwerkzeuge. Sie sind ein stiller, körperlicher Kommentar zu dem, was in uns vorgeht, lange bevor wir es selbst in Worte fassen könnten.</p>
          <p class="vb-intro" style="margin-bottom:0;">Wer den eigenen Händen mit dieser Aufmerksamkeit begegnet, entdeckt darin oft ein überraschend stimmiges Echo des eigenen Enneagrammtyps – und einen weiteren, sehr körpernahen Zugang zur eigenen inneren Landkarte.</p>
        </div>

        ${bookTip("hinter-der-leidenschaft", "Die neun Wunden des Enneagramms – tiefgreifende Analyse der Urwunde hinter jeder Leidenschaft, mit konkreten Heilungswegen für alle 9 Typen.", "Hinter der Leidenschaft")}
        ${bookTip("leidenschaft-und-heilung", "27 Subtypen – Leidenschaften, Tugenden und Heilungswege direkt aus der therapeutischen Praxis.", "Leidenschaft und Heilung")}
        ${bookTip("heilung-als-erinnerung", "Heilung nicht als Reparatur, sondern als Erinnerung an das, was wir eigentlich sind – ein tiefgründiger Blick auf Gesundheit und Ganzheit.", "Heilung als Erinnerung")}
        ${relatedLinks([
          {route:"enneagramm-reflexzonentherapie", label:"Enneagramm meets Reflexzonentherapie"},
          {route:"enneagramm-zahnpsychosomatik", label:"Enneagramm meets Zahnpsychosomatik"},
          {route:"drei-zentren", label:"Schaubild: Drei Zentren"},
          {route:"wunden", label:"Die 9 Wunden der Enneagrammtypen"},
        ])}
      </div>
    </div>
  `);
}



// \u2500\u2500\u2500 Enneagramm meets Akupunktur \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500

function enneagrammAkupunkturPage() {
  return shell(`
    <div class="page-container">
      ${pageHeader('enneagramm-akupunktur')}
      <div class="page-content">
        <p class="eyebrow">Wissen \u00b7 K\u00f6rperarbeit</p>
        <h1 class="section-title">Enneagramm meets Akupunktur</h1>
        <h2 class="section-title" style="font-size:1.2rem;font-weight:600;margin:0 0 1.4rem;color:var(--muted);">Die Landkarte der Psyche trifft auf den Meridianfluss des K\u00f6rpers</h2>

        <blockquote class="vb-blockquote" style="margin-bottom:1.8rem;">
          <p class="vb-intro">Zwei Spiegel desselben Kosmos: Das Enneagramm ist ein geometrisches Symbol der Psyche, ein Kreis mit neun Punkten, der die Landkarte menschlicher Motivation zeichnet. Die Traditionelle Chinesische Medizin (TCM) kennt mit ihren Meridianen und Akupunkturpunkten ein ebenso altes, ebenso feinmaschiges Abbildungssystem \u2013 nur eben f\u00fcr den K\u00f6rper und seinen Energiefluss. Beide Systeme gehen von derselben Grundannahme aus: Der Mensch ist keine isolierte Maschine, sondern ein dynamischer Mikrokosmos, der mit universellen Gesetzen in Resonanz steht.</p>
          <p class="vb-intro">Wo das Enneagramm die psychologischen Fixierungen, emotionalen Muster und mentalen Filter der neun Typen kartografiert, macht die Akupunktur den Fluss der Lebensenergie \u2013 das Qi \u2013 und dessen Blockaden sichtbar. Legt man beide Landkarten \u00fcbereinander, entsteht ein Zugang, der \u00fcber das rein Psychologische hinausgeht: ein holistischer Blick auf psychosomatische Heilung, bei dem seelisches Muster und k\u00f6rperlicher Energiefluss als zwei Ausdrucksformen derselben Wirklichkeit erscheinen.</p>
          <p class="vb-intro" style="margin-bottom:0;">Die folgenden Abschnitte zeigen, wie sich die drei Zentren des Enneagramms in der Lehre der F\u00fcnf Wandlungsphasen wiederfinden, wie Fixierung sich als energetische Stauung lesen l\u00e4sst \u2013 und wie die inneren Linien des Enneagramms sich wie Nadel-Pfade durch den K\u00f6rper ziehen.</p>
        </blockquote>

        <div style="margin:0 0 2rem;border-radius:12px;overflow:hidden;box-shadow:0 2px 12px rgba(0,0,0,0.15);">
          <img src="./assets/portraits/enneagramm-akupunktur-de.jpeg" alt="\u00dcbersicht: Enneagramm-Zentrum, TCM-Element, somatischer Schwerpunkt und Akupunktur-L\u00f6sung im Zusammenspiel" style="width:100%;display:block;" loading="lazy" />
          <p style="text-align:center;font-size:0.78rem;color:var(--muted);margin:0;padding:0.5rem 0.5rem 0.7rem;">Die drei Enneagramm-Zentren im Spiegel der F\u00fcnf Wandlungsphasen: Zentrum, TCM-Element, somatischer Schwerpunkt und die jeweilige Akupunktur-L\u00f6sung im \u00dcberblick.</p>
        </div>

        <div class="vb-section" style="max-width:100%;margin-bottom:2rem;">
          <h2 style="font-size:1.1rem;font-weight:700;margin:0 0 0.8rem;color:var(--ink);">1. Das triadische Grundprinzip: Die drei Zentren und die Wandlungsphasen</h2>
          <p class="vb-intro">Das Enneagramm gruppiert seine neun Typen seit jeher in drei Zentren: das K\u00f6rper- beziehungsweise Instinktzentrum (Typ 8, 9, 1) mit seinem Ringen um Autonomie, Wut und Grenzen; das Herz- oder Gef\u00fchlszentrum (Typ 2, 3, 4) mit seinem Kreisen um Identit\u00e4t, Scham und Wertsch\u00e4tzung; und das Kopf- oder Denkzentrum (Typ 5, 6, 7) mit seinem Ringen um Sicherheit, Angst und Orientierung.</p>
          <p class="vb-intro">In der Traditionellen Chinesischen Medizin findet sich eine verwandte Dreigliederung wieder \u2013 nur feiner aufgef\u00e4chert: die Lehre der F\u00fcnf Wandlungsphasen (Holz, Feuer, Erde, Metall, Wasser) und das Zusammenspiel der ihnen zugeordneten Funktionskreise. Jeder Enneagrammtyp zeigt dabei typische somatische Stressmuster, die sich \u00fcber bestimmte Meridiane und Wandlungsphasen abzeichnen.</p>
          <p class="vb-intro" style="margin-bottom:0;">Ein Beispiel macht das greifbar: Der Kopf-Typ F\u00fcnf zeigt unter Druck h\u00e4ufig Ersch\u00f6pfungssignale im Wasser-Element \u2013 dem Funktionskreis von Niere und Blase, traditionell mit Urangst und mentaler Ersch\u00f6pfung verbunden. Der Herz-Typ Zwei dagegen meldet sich bei emotionaler Vernachl\u00e4ssigung eher \u00fcber das Feuer-Element \u2013 Herz und D\u00fcnndarm, in der TCM der Sitz des Shen, des Geistes.</p>
        </div>

        <div class="vb-section" style="max-width:100%;margin-bottom:2rem;">
          <h2 style="font-size:1.1rem;font-weight:700;margin:0 0 0.8rem;color:var(--ink);">2. Psychosomatische Entsprechungen: Fixierung als energetische Stauung</h2>
          <p class="vb-intro">In der Akupunktur entsteht Krankheit klassischerweise durch eine Stauung (Qi Zhi) oder einen Mangel (Xu) von Energie. Die Enneagramm-Fixierung l\u00e4sst sich als energetisches Pendant dazu lesen: eine mentale und emotionale Einbahnstra\u00dfe, auf der dieselbe Reaktion immer wieder abl\u00e4uft, statt frei zu flie\u00dfen.</p>
          <p class="vb-intro">Bei den K\u00f6rper-Typen (8, 9, 1) h\u00e4lt sich diese Spannung typischerweise im Muskel- und Fasziensystem \u2013 dem Holz-Element, dem Leber-Meridian zugeordnet, der in der TCM f\u00fcr den Qi-Fluss und f\u00fcr gesunde Wut beziehungsweise gesunde Durchsetzungskraft zust\u00e4ndig ist. Chronische Verleugnung eigener Bed\u00fcrfnisse schl\u00e4gt sich hier in muskul\u00e4ren Blockaden nieder.</p>
          <p class="vb-intro" style="margin-bottom:0;">Bei den Kopf-Typen (5, 6, 7) staut sich Energie eher im Kopf selbst, w\u00e4hrend der Bodenkontakt verloren geht. Punkte wie Niere 1 \u2013 die \u203aSprudelnde Quelle\u2039 an der Fu\u00dfsohle \u2013 oder andere Erdungspunkte binden das \u00fcberhitzte Mentalsystem gezielt wieder an das Erd- und Wassersystem des K\u00f6rpers an.</p>
        </div>

        <div class="vb-section" style="max-width:100%;margin-bottom:2rem;">
          <h2 style="font-size:1.1rem;font-weight:700;margin:0 0 0.8rem;color:var(--ink);">3. Dynamische Evolution: Die Linien des Enneagramms als Nadel-Pfade</h2>
          <p class="vb-intro">Das Enneagramm ist keine statische Schublade. \u00dcber die inneren Linien \u2013 die Stress- und Integrationspunkte \u2013 ver\u00e4ndert sich der Energiefluss eines Typs je nach innerer Verfassung. Unter Stress springt ein Typ gleichsam auf einen anderen Punkt: Die kontrollierte Eins etwa nimmt unter Druck die chaotischeren Z\u00fcge der Vier an.</p>
          <p class="vb-intro">In der Sprache der Akupunktur l\u00e4sst sich dieser Sprung als abrupte Umlenkung des Energieflusses auf einen \u203aNotfall-Meridian\u2039 beschreiben \u2013 der K\u00f6rper sucht sich unter Belastung einen anderen Weg, um mit der Spannung umzugehen. Bewusste Akupunktur-Arbeit kann hier als Katalysator wirken: Sie hilft dem K\u00f6rper, alte reaktive Muster loszulassen, sodass der Mensch leichter Zugang zu den positiven Qualit\u00e4ten seines Integrations- und Wachstumspunktes findet, statt in der Stressreaktion gefangen zu bleiben.</p>
        </div>

        <div class="vb-section" style="max-width:100%;margin-bottom:2rem;background:var(--ivory);border:1px solid var(--border);border-radius:12px;padding:1.4rem 1.6rem;border-left:4px solid var(--copper);">
          <h2 style="font-size:1.05rem;font-weight:700;margin:0 0 0.7rem;color:var(--ink);">Wichtiger Hinweis: Akupunktur geh\u00f6rt in erfahrene H\u00e4nde</h2>
          <p class="vb-intro" style="margin-bottom:0;">Die genaue Anwendung der chinesischen Akupunktur ist eine hohe Kunst und sollte ausschlie\u00dflich von einem Therapeuten mit jahrzehntelanger Erfahrung ausge\u00fcbt werden. Wie bei jeder Heilkunst reicht Wissen allein nicht aus \u2013 es braucht ebenso viel gelebte Praxiserfahrung. Ein paar Jahre Ausbildung gen\u00fcgen sicher nicht, um in dieser naturheilkundlichen Disziplin wirklich zum Meister zu reifen. Wer sich f\u00fcr Akupunktur interessiert, sollte deshalb gezielt nach einem entsprechend erfahrenen Therapeuten suchen, statt die Nadelsetzung auf eigene Faust zu versuchen.</p>
        </div>

        <div class="vb-section" style="max-width:100%;margin-bottom:2rem;">
          <h2 style="font-size:1.1rem;font-weight:700;margin:0 0 0.8rem;color:var(--ink);">Akupressur: der Weg in Eigenregie</h2>
          <p class="vb-intro">Wer nicht bis zum n\u00e4chsten Termin bei einem erfahrenen Therapeuten warten m\u00f6chte, findet in der verwandten Akupressur einen Zugang, der sich in Eigenregie \u00fcben l\u00e4sst \u2013 mit \u00e4hnlich guten Effekten wie die Nadelakupunktur, nur ohne Nadel. Vier K\u00f6rperzonen kommen dabei zum Einsatz: Gesichtsakupressur, Handakupressur, Fu\u00dfakupressur und Ohrakupressur \u2013 jeweils eigene Punktesysteme, die sich unabh\u00e4ngig voneinander oder kombiniert nutzen lassen.</p>
          <p class="vb-intro">Dieser Kompass behandelt Akupressur bereits auf allen 27 Subtyp-Detailseiten im Abschnitt \u203aRegulieren \u00b7 K\u00f6rperarbeit & Akupressur\u2039 \u2013 ein Klick auf den eigenen Subtyp f\u00fchrt direkt dorthin, statt nur auf die allgemeine Profilseite:</p>
          <div style="display:flex;flex-wrap:wrap;gap:0.5rem;margin:0 0 1.2rem;">
            ${[1,2,3,4,5,6,7,8,9].flatMap(n => ['SE','SO','SX'].map(inst => {
              const code = (inst + n).toLowerCase();
              const col = (typeof TYPE_COLORS !== 'undefined' ? TYPE_COLORS[n] : null) || 'var(--copper)';
              return `<a href="javascript:void(0)" data-route="subtype/${code}|subtype-section-regulieren" style="font-size:0.8rem;font-weight:700;padding:0.3rem 0.7rem;border-radius:20px;border:1.5px solid ${col};color:${col};text-decoration:none;">${inst}${n}</a>`;
            })).join('')}
          </div>
          <p class="vb-intro" style="margin-bottom:0;">Wichtig dabei: Akupressur entfaltet ihre Wirkung erst bei l\u00e4ngerer, regelm\u00e4\u00dfiger Anwendung. Und sie funktioniert nicht rein kopfgesteuert \u2013 wer die Punkte nur mechanisch abhakt, wird wenig sp\u00fcren. Erst wenn die \u00dcbung auch intuitiv, herz- und bauchfokussiert erfolgt, wenn man sich also bewusst mit sich selbst und dem eigenen K\u00f6rper als unmittelbarem Ausdruck des menschlichen Seins besch\u00e4ftigt, stellen sich langfristig deutliche Verbesserungen ein. Wie innen, so au\u00dfen \u2013 dieser alte Grundsatz gilt f\u00fcr die Akupressur ganz besonders.</p>
        </div>

        <div class="vb-section" style="max-width:100%;margin-top:2rem;">
          <h2 style="font-size:1.1rem;font-weight:700;margin:0 0 0.8rem;color:var(--ink);">Fazit: Zwei Sprachen f\u00fcr denselben Zustand</h2>
          <p class="vb-intro">Die Synthese aus Enneagramm und Akupunktur verbindet die Tiefenpsychologie der Motivation mit der jahrtausendealten Weisheit der Meridianlehre. Das Enneagramm beantwortet das Warum des Leidens und der immer gleichen Verhaltensmuster \u2013 die innere Logik hinter der Fixierung. Die Akupunktur wandelt dieses Wissen auf k\u00f6rperlich-energetischer Ebene, sie zeigt das Wie: wo genau sich die Spannung staut und wie sie sich wieder l\u00f6sen l\u00e4sst.</p>
          <p class="vb-intro" style="margin-bottom:0;">Zusammen ergeben beide Systeme ein m\u00e4chtiges, analoges Werkzeug f\u00fcr ganzheitliche Balance \u2013 von der inneren Haltung bis zum feinstofflichen Energiefluss.</p>
        </div>

        ${bookTip("hinter-der-leidenschaft", "Die neun Wunden des Enneagramms \u2013 tiefgreifende Analyse der Urwunde hinter jeder Leidenschaft, mit konkreten Heilungswegen f\u00fcr alle 9 Typen.", "Hinter der Leidenschaft")}
        ${bookTip("leidenschaft-und-heilung", "27 Subtypen \u2013 Leidenschaften, Tugenden und Heilungswege direkt aus der therapeutischen Praxis.", "Leidenschaft und Heilung")}
        ${bookTip("heilung-als-erinnerung", "Heilung nicht als Reparatur, sondern als Erinnerung an das, was wir eigentlich sind \u2013 ein tiefgr\u00fcndiger Blick auf Gesundheit und Ganzheit.", "Heilung als Erinnerung")}
        ${relatedLinks([
          {route:"enneagramm-reflexzonentherapie", label:"Enneagramm meets Reflexzonentherapie"},
          {route:"drei-zentren", label:"Schaubild: Drei Zentren"},
          {route:"subtype/se1", label:"Subtyp SE1"},
          {route:"subtype/so4", label:"Subtyp SO4"},
          {route:"subtype/sx7", label:"Subtyp SX7"},
        ])}
      </div>
    </div>
  `);
}

// \u2500\u2500\u2500 Enneagramm meets Astrologie \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500

function enneagrammAstrologiePage() {
  function card(p) {
    const n = parseInt((p.subtyp||'').replace(/[^0-9]/,'').charAt(0));
    const col = (typeof TYPE_COLORS !== 'undefined' ? TYPE_COLORS[n] : null) || 'var(--copper)';
    return `<div class="kf-card" data-route="${p.route}" onclick="go('${p.route}')" style="cursor:pointer;border-radius:10px;border:1px solid var(--border);padding:1rem 1.1rem;background:var(--ivory);">
      <div style="font-size:0.7rem;font-weight:700;letter-spacing:0.12em;text-transform:uppercase;color:${col};margin-bottom:0.25rem;">${p.subtyp}</div>
      <div style="font-weight:700;font-size:1rem;color:var(--ink);margin-bottom:0.3rem;">${p.name}</div>
      <div style="font-size:0.85rem;color:var(--muted);line-height:1.5;">${p.teaser}</div>
    </div>`;
  }
  return shell(`
    <div class="page-container">
      ${pageHeader('Enneagramm meets Astrologie')}
      <h1 style="font-family:'EB Garamond',serif;font-size:2rem;color:var(--ink);margin:1.2rem 0 0.5rem;line-height:1.2;">Enneagramm meets Astrologie</h1>
      <p class="psycho-intro">Zwei Systeme \u2013 ein Mensch. Astrologie und Enneagramm beschreiben denselben Kern einer Pers\u00f6nlichkeit aus verschiedenen Blickwinkeln: der kosmische Bauplan des Radix-Horoskops und die psychologische Landkarte der 9 Kernmotivationen. In diesen Analysen treffen beide aufeinander und zeigen, wie energetische Anlagen und unbewusste \u00dcberlebensstrategien ineinandergreifen.</p>
      <div style="display:flex;flex-direction:column;gap:1rem;max-width:100%;margin-bottom:2rem;">
        ${ASTROLOGIE_PORTRAITS.map(card).join('')}
      </div>
      ${relatedLinks([
        {route:"beruehmte-persoenlichkeiten", label:"Ber\u00fchmte Pers\u00f6nlichkeiten \u2013 Portr\u00e4ts"},
        {route:"kriminalpsychologie", label:"Kriminalpsychologie"},
        {route:"psychogramme", label:"Psychogramme"},
        {route:"planetenzuordnungen", label:"Schaubild: Planeten & Trabanten des Sonnensystems"},
        {route:"enneagramm-odyssee", label:"Enneagramm meets Odyssee"},
      ])}
    </div>
  `);
}

// \u2500\u2500\u2500 Enneagramm meets Odyssee \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500

function enneagrammOdysseePage() {
  const TYPEN_ODYSSEE = [
    {
      typ: 1, titel: "Das Gesetz der G\u00f6tter und die Pr\u00fcfung der Ordnung",
      text: "\u00dcber der ganzen Odyssee wacht ein unsichtbares Regelwerk: der Zorn Poseidons, der die Irrfahrt \u00fcberhaupt erst ausl\u00f6st, und die k\u00fchle, gerechte F\u00fcrsorge Athenes, die immer nur eingreift, wenn das Ma\u00df, das Rechte, endlich wiederhergestellt werden kann. Nichts geschieht in diesem Kosmos willk\u00fcrlich \u2013 jede Verfehlung wird beantwortet, jede Hybris bestraft, jede Treue irgendwann belohnt. Genau in dieser unerbittlichen kosmischen Buchhaltung erkennt sich Typ 1 wieder: Die Reise verlangt absolute moralische Ausrichtung, das st\u00e4ndige Ringen um das, was richtig ist.<br><br>Die Versuchung der Eins besteht darin, sich selbst als Richter \u00fcber die Welt aufzuschwingen oder in bittere Frustration zu geraten, wenn das Schicksal \u2013 wie so oft bei Odysseus \u2013 zutiefst ungerecht erscheint. Die Entwicklungsaufgabe der Eins in der Odyssee ist das Erlernen von Hingabe: die Erkenntnis, dass wahre Ordnung nicht durch das erzwingende Ego entsteht, sondern durch das Akzeptieren der h\u00f6heren, unvollkommenen Wirklichkeit."
    },
    {
      typ: 2, titel: "Kalypso und die Falle des rettenden Paradieses",
      text: "Sieben Jahre lang h\u00e4lt die Nymphe Kalypso Odysseus auf ihrer Insel Ogygia gefangen \u2013 nicht mit Ketten, sondern mit F\u00fcrsorge. Sie pflegt ihn, verw\u00f6hnt ihn, verspricht ihm sogar Unsterblichkeit und ewige Jugend an ihrer Seite. Ein Paradies, gebaut aus reiner Zuwendung. Die einzige Bedingung: Er darf niemals wieder gehen.<br><br>Genau darin verbirgt sich die Schattenseite von Typ 2. Die Zwei gibt im \u00dcberma\u00df, rettet, n\u00e4hrt und umsorgt \u2013 kn\u00fcpft daran jedoch die unbewusste Bedingung, daf\u00fcr gebraucht und geliebt zu werden. Kalypso illustriert diese stille Gefangenschaft in der Beziehungsfalle: Der andere wird durch F\u00fcrsorge \u201ebesessen\u201c, ohne dass es sich wie Besitzergreifung anf\u00fchlt \u2013 es f\u00fchlt sich wie Liebe an. Der Ausweg f\u00fcr die Zwei liegt darin, den Gegen\u00fcber wirklich freizugeben und zu erkennen: Wahre Liebe erzwingt keine Bindung."
    },
    {
      typ: 3, titel: "Die R\u00fcstung des Achill und das Schlachten der Sonnenrinder",
      text: "Zweimal begegnet Odysseus auf dieser Reise der Verf\u00fchrung durch Glanz und Erfolg. Da ist die R\u00fcstung des gefallenen Helden Achill \u2013 der Mantel des Ruhms, um den sich sogar die gr\u00f6\u00dften Krieger streiten, weil er verspricht, wer immer ihn tr\u00e4gt, werde selbst zur Legende. Und da ist, weit dramatischer, das Schlachten der heiligen Sonnenrinder des Helios: Die hungernden Gef\u00e4hrten missachten das strengste Tabu der Reise, weil der unmittelbare Erfolg \u2013 satt werden, jetzt, sofort \u2013 wichtiger erscheint als jede sp\u00e4tere Konsequenz.<br><br>F\u00fcr die Drei ist die Odyssee eine Lektion im Durchschauen des Scheins. Die Pers\u00f6nlichkeit sch\u00fctzt sich durch Leistung und eine polierte Fassade, durch das Bild, das andere von ihr haben sollen. Die Pr\u00fcfung besteht darin, die R\u00fcstung endlich abzulegen und zu erkennen: Der eigene Wert h\u00e4ngt nicht am Beifall der Mitwelt, sondern am unverf\u00e4lschten Sein darunter."
    },
    {
      typ: 4, titel: "Der Gesang der Sirenen und die Verf\u00fchrung des Schmerzes",
      text: "Odysseus wei\u00df, was ihn erwartet, und l\u00e4sst sich trotzdem an den Mast binden, um es zu h\u00f6ren: den Gesang der Sirenen. Er ist von ber\u00fcckender Sch\u00f6nheit, zutiefst melancholisch \u2013 und t\u00f6dlich zugleich. Kein Seefahrer, der ihn h\u00f6rt, kann ihm widerstehen; alle steuern ihre Schiffe in den sicheren Untergang, gezogen von einer Musik, die verspricht, den tiefsten Schmerz in etwas Erhabenes zu verwandeln.<br><br>Die Sirenen symbolisieren die Sucht von Typ 4 nach intensivem emotionalem Drama, nach Sehnsucht und dem Schmerz des Verlorenen. Der Gesang verspricht eine Erh\u00f6hung des Leids zu etwas Magischem, fast Heiligem. Die Entwicklungspr\u00fcfung der Vier besteht darin, den Gesang der eigenen Melancholie zu h\u00f6ren, ohne ihm ins Verderben zu folgen \u2013 Gef\u00fchle also wirklich wahrzunehmen, ohne sich von ihnen ertr\u00e4nken zu lassen."
    },
    {
      typ: 5, titel: "Der Abstieg in den Hades und das schattige Wissen",
      text: "Um \u00fcberhaupt einen Weg nach Hause zu finden, muss Odysseus zuerst dorthin, wo niemand freiwillig hingeht: in die Unterwelt, den Hades, um den blinden Seher Teiresias nach seinem Schicksal zu befragen. Es ist ein Ort v\u00f6lliger Dunkelheit, \u00e4u\u00dferster Distanz zum Leben \u2013 und zugleich der Ort, an dem sich das reinste, unverstellte Wissen findet.<br><br>Diese Etappe spiegelt exakt den R\u00fcckzug von Typ 5 wider. Die F\u00fcnf zieht sich aus der lebendigen, oft \u00fcberfordernden Au\u00dfenwelt in die innere Gedankenwelt zur\u00fcck, beobachtet das Leben aus sicherer Entfernung und sammelt Wissen als Schutzschild gegen eine als bedrohlich erlebte Realit\u00e4t. Der Mythos lehrt jedoch etwas Entscheidendes: Der Aufenthalt im Hades dient nur der Orientierung, nicht dem dauerhaften Wohnen. Die F\u00fcnf muss die Schattenwelt des blo\u00dfen Beobachtens irgendwann wieder verlassen und ins k\u00f6rperliche, emotionale Leben zur\u00fcckkehren."
    },
    {
      typ: 6, titel: "Skylla, Charybdis und der Windbeutel des Aiolos",
      text: "Kaum eine Figur der Odyssee kennt die Gefahr so gut wie die Sechs \u2013 und wird trotzdem, oder gerade deshalb, immer wieder von ihr eingeholt. Da ist der Windbeutel des Windgottes Aiolos: ein Geschenk, das die sichere Heimfahrt garantieren w\u00fcrde, h\u00e4tten die misstrauischen Gef\u00e4hrten ihn nicht in Sichtweite der Heimat aus Argwohn ge\u00f6ffnet und damit das Chaos selbst entfesselt. Und da ist die ber\u00fcchtigte Meerenge zwischen Skylla, dem sechsk\u00f6pfigen Ungeheuer, und Charybdis, dem alles verschlingenden Strudel \u2013 eine Passage, bei der jede Entscheidung ein Opfer verlangt.<br><br>Dies ist das eigentliche Territorium der Sechs: die Dauerprojektion von Gefahren, das st\u00e4ndige Schwanken zwischen l\u00e4hmender Angst und trotzigem Mut, das nie endende Abw\u00e4gen des kleineren \u00dcbels. Die Reise verlangt von der Sechs den \u00dcbergang von \u00e4u\u00dferer R\u00fcckversicherung \u2013 oder der Panik-L\u00e4hmung, wenn diese fehlt \u2013 zu einem inneren Vertrauen, das auch mitten im Sturm tr\u00e4gt."
    },
    {
      typ: 7, titel: "Kirke, die Lotosesser und das Ausweichen vor dem Schmerz",
      text: "Kaum haben die Gef\u00e4hrten die Insel der Zauberin Kirke betreten, verwandelt sie sie mit berauschenden Kr\u00e4utern und einem Festmahl in Schweine \u2013 ein Zustand puren, gedankenlosen Genusses, in dem die eigentliche Heimreise, das eigentliche Ziel, restlos vergessen wird. Erst Odysseus' Klugheit und der Beistand des Gottes Hermes bewahren ihn selbst vor diesem Schicksal.<br><br>Kirkes Insel steht exemplarisch f\u00fcr die Fixierung von Typ 7: das st\u00e4ndige Ausweichen vor unangenehmen Gef\u00fchlen durch Ablenkung, Konsum, neue Pl\u00e4ne und ein optimistisches, beinahe magisches Denken. Die Gefahr der Sieben besteht darin, in den Freuden der Fantasie oder des Augenblicks zu stranden und dadurch genau die Tiefe der Transformation zu verpassen, die eigentlich das Ziel der Reise ist. Die Sieben muss lernen, auch den Schmerz anzunehmen, um zu echter, gelassener N\u00fcchternheit zu finden."
    },
    {
      typ: 8, titel: "Der Zyklop Polyphem und die rohe Gewaltsamkeit",
      text: "Der ein\u00e4ugige Riese Polyphem kennt keine Gesetze au\u00dfer seinem eigenen Willen. Er vertraut allein auf seine gigantische Kraft, sperrt Odysseus und seine M\u00e4nner in seine H\u00f6hle und verschlingt sie einen nach dem anderen, rasend vor unkontrollierter Wut. Sein einzelnes Auge liest sich wie ein Sinnbild f\u00fcr eine radikal eingeschr\u00e4nkte, gnadenlos zweigeteilte Sichtweise: stark oder schwach, Macht oder Ohnmacht \u2013 ein Dazwischen gibt es f\u00fcr ihn nicht.<br><br>Polyphem verk\u00f6rpert die unintegrierte Schattenseite von Typ 8: die exzessive Selbstbehauptung, das vollst\u00e4ndige Abstreifen jeglicher Verletzlichkeit, das Diktieren eigener Regeln allein durch H\u00e4rte. Erst als Odysseus den Zyklopen durch List \u2013 Geist statt roher Gewalt \u2013 blendet und entkommt, wird die Festung der blo\u00dfen Macht endg\u00fcltig gebrochen. Die Acht lernt hier ihre entscheidende Lektion: Wahre St\u00e4rke liegt nicht in der Eskalation, sondern in der B\u00e4ndigung des eigenen Exzesses und im mutigen Zulassen von Herzensw\u00e4rme."
    },
    {
      typ: 9, titel: "Das Vergessen im Land der Lotosesser",
      text: "Gleich zu Beginn der Irrfahrt, noch bevor die gro\u00dfen Pr\u00fcfungen \u00fcberhaupt beginnen, ger\u00e4t die Mannschaft an die K\u00fcste der Lotosesser. Wer von der s\u00fc\u00dfen Lotosfrucht kostet, versinkt in einem Zustand gl\u00fcckseliger Gleichg\u00fcltigkeit \u2013 vergisst Heimat, Auftrag und Sehnsucht und will f\u00fcr immer dort bleiben, bet\u00e4ubt von einem Frieden, der keiner ist.<br><br>Genau hier liegt das Herzst\u00fcck der Problematik von Typ 9: die psychische Tr\u00e4gheit, jene stille Selbstbet\u00e4ubung, die im Enneagramm als \u203aSloth\u2039 bezeichnet wird. Die Neun neigt dazu, sich selbst zu vergessen, jedem Konflikt auszuweichen und sich im scheinbaren Wohlbefinden des Status quo schlafen zu legen. Das Land der Lotosesser f\u00fchlt sich friedlich an, ist in Wahrheit aber der Tod der eigenen Bestimmung. Die Reise der Neun beginnt genau an diesem Punkt \u2013 beim Erwachen aus der Narkose und dem stillen, aber entscheidenden Entschluss, das eigene Leben endlich wieder aktiv in die Hand zu nehmen."
    },
  ];

  function typCard(t) {
    const col = (typeof TYPE_COLORS !== 'undefined' ? TYPE_COLORS[t.typ] : null) || 'var(--copper)';
    return `<div class="vb-section" style="max-width:100%;border-left:3px solid ${col};padding-left:1.1rem;margin-bottom:1.4rem;">
      <div style="font-size:0.72rem;font-weight:700;letter-spacing:0.1em;text-transform:uppercase;color:${col};margin-bottom:0.4rem;">Typ ${t.typ}</div>
      <h3 style="font-size:1.05rem;font-weight:700;margin:0 0 0.6rem;color:var(--ink);">${t.titel}</h3>
      <p class="vb-intro" style="margin:0;">${t.text}</p>
    </div>`;
  }

  return shell(`
    <div class="page-container">
      ${pageHeader('enneagramm-odyssee')}
      <div class="page-content">
        <p class="eyebrow">Wissen \u00b7 Mythologie</p>
        <h1 class="section-title">Enneagramm meets Odyssee</h1>
        <h2 class="section-title" style="font-size:1.2rem;font-weight:600;margin:0 0 1.4rem;color:var(--muted);">Die Heldenreise als Landkarte der neun Fixierungen</h2>

        <blockquote class="vb-blockquote" style="margin-bottom:1.8rem;">
          <p class="vb-intro">Manche Geschichten sind so alt und so oft erz\u00e4hlt worden, dass sie l\u00e4ngst aufgeh\u00f6rt haben, nur Geschichten zu sein \u2013 sie sind zu Landkarten der menschlichen Seele geworden. Die Odyssee Homers ist eine davon: die zehnj\u00e4hrige Irrfahrt eines Mannes, der nichts weiter will, als nach Hause zu kommen, und dabei an jeder Station von einer anderen Versuchung, einem anderen Ungeheuer, einer anderen Illusion aufgehalten wird.</p>
          <p class="vb-intro">Liest man diese Stationen durch die Brille des Enneagramms, entsteht ein verbl\u00fcffend genaues Bild: Jede Etappe der Reise \u2013 die Insel der Kalypso, der Gesang der Sirenen, der Zyklop Polyphem, der Abstieg in den Hades \u2013 l\u00e4sst sich einem der neun Typen zuordnen, als h\u00e4tte Homer bereits vor fast dreitausend Jahren die neun Grundmuster menschlicher Fixierung in Bilder gefasst. Diese Parallele l\u00e4sst sich nicht als zuf\u00e4lliges Anschauungsmaterial lesen, sondern als metaphorische Blaupause f\u00fcr die menschliche Transformation: Die Reise von Odysseus ist der Weg der Seele, die aus der Illusion des Ego (dem Krieg von Troja) aufbricht, um zu ihrer wahren Essenz (Ithaka) zur\u00fcckzukehren.</p>
          <p class="vb-intro">Die Pr\u00fcfung auf dieser Reise liegt darin, dass jeder Typ an den spezifischen Fixierungen seiner Pers\u00f6nlichkeit scheitern kann. Erst wenn die Heldenfigur die Schattenseiten und Versuchungen der jeweiligen Etappe durchschaut, wird der Weg nach Hause frei.</p>
        </blockquote>

        <div style="margin:0 0 2rem;border-radius:12px;overflow:hidden;box-shadow:0 2px 12px rgba(0,0,0,0.15);">
          <img src="./assets/portraits/enneagramm-odyssee-de.jpeg" alt="Die Odyssee: Die Reise des Enneagramms \u2013 Odysseus' Schiff umgeben von den neun Stationen seiner Reise" style="width:100%;display:block;" loading="lazy" />
          <p style="text-align:center;font-size:0.78rem;color:var(--muted);margin:0;padding:0.5rem 0.5rem 0.7rem;">Odysseus' Schiff im Zentrum, umgeben von den Schl\u00fcsselmomenten seiner Reise, die die neun Enneagrammtypen repr\u00e4sentieren: oben die Begegnungen mit dem Zyklopen (Typ 8), der Zauberin Kirke (Typ 7) und die Passage zwischen Skylla und Charybdis (Typ 6); unten die Sirenen (Typ 4), die Lotosesser (Typ 9) und die R\u00fcstung des Achill (Typ 3); im Hintergrund der Hades (Typ 5), der g\u00f6ttliche Zorn (Typ 1) und Kalypso (Typ 2).</p>
        </div>

        <div class="vb-section" style="max-width:100%;">
          ${TYPEN_ODYSSEE.map(typCard).join('')}
        </div>

        ${bookTip("wer-du-wirklich-bist-band-1", "Die neun Typen in ihrer Tiefe \u2013 Schutzmuster, Leidenschaften und der Weg zur Essenz. Der erste Band der Trilogie, die das Enneagramm lebendig macht.", "Wer du wirklich bist \u2013 Band 1")}
        ${bookTip("die-verborgene-dynamik-der-27-subtypen", "Wie Instinkt und Typ zusammenwirken \u2013 die verborgene Dynamik hinter den 27 Subtypen, jenseits der neun Grundtypen.", "Die verborgene Dynamik der 27 Subtypen")}
        ${bookTip("die-27-persoenlichkeiten-des-enneagramms", "27 Charakterprofile im Vergleich \u2013 wie sich die Subtypen desselben Typs voneinander unterscheiden.", "Die 27 Pers\u00f6nlichkeiten des Enneagramms")}
        <a class="book-tip" href="https://www.amazon.de/Die-Odyssee-Schmuckausgabe-Motiv-Farbschnitt-Christopher/dp/345864573X?linkCode=ll2&tag=enneagrammkom-21&linkId=63836859f1c80e6d43e322266418842b&ref_=as_li_ss_tl" target="_blank" rel="noopener sponsored">
          <span class="book-tip__icon">\ud83d\udcd6</span>
          <div class="book-tip__text">
            <strong>Buchtipp: \u00bbDie Odyssee \u2013 Schmuckausgabe\u00ab</strong>
            <span>Homers Epos \u00fcber die legend\u00e4ren Irrfahrten des Odysseus \u2013 zur Vertiefung als hochwertige, illustrierte Schmuckausgabe.</span>
          </div>
          <span class="book-tip__arrow">\u2192</span>
        </a>
        ${relatedLinks([
          {route:"enneagramm-astrologie", label:"Enneagramm meets Astrologie"},
          {route:"enneagramm-wohnraumarchitektur", label:"Enneagramm meets Wohnraumarchitektur"},
          {route:"beruehmte-persoenlichkeiten", label:"Ber\u00fchmte Pers\u00f6nlichkeiten \u2013 Portr\u00e4ts"},
          {route:"wunden", label:"Die 9 Wunden der Enneagrammtypen"},
          {route:"tritypen", label:"Die 27 Tritypen des Enneagramms"},
        ])}
      </div>
    </div>
  `);
}

// \u2500\u2500\u2500 Enneagramm meets Wohnraumarchitektur \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500

function enneagrammWohnraumarchitekturPage() {
  const ZENTREN_WOHNEN = [
    {
      zentrum: "Das Kopf-Zentrum (Typ 5, 6, 7): R\u00fcckzug, Sicherheit und geistiger Freiraum",
      intro: "Menschen aus dem Kopf-Zentrum leben prim\u00e4r im Verstand. Ihr Zuhause muss in erster Linie ein sicherer Hafen sein, der sie vor einer als \u00fcberw\u00e4ltigend empfundenen Welt sch\u00fctzt oder ihnen den n\u00f6tigen intellektuellen Freiraum gibt.",
      typen: [
        { typ: 5, titel: "Der Beobachter \u2013 Das minimalistische Observatorium", punkte: [
          "<strong>Das Wohnkonzept:</strong> Die F\u00fcnf braucht vor allem eines: minimalistischen R\u00fcckzug und Ruhe. \u00dcberfl\u00fcssiger Ballast wird konsequent aussortiert. Ihr Raum gleicht oft einem durchdachten Refugium, in dem jedes Buch seinen festen Platz hat.",
          "<strong>Die Raum-Psychologie:</strong> Ein gem\u00fctlicher, uneinsehbarer Lesesessel, gedimmtes Licht und klare Linien sch\u00fctzen die F\u00fcnf vor energetischer Reiz\u00fcberflutung. Hier kann sie sich zur\u00fcckziehen, beobachten und in ihre Wissenswelten abtauchen, ohne gest\u00f6rt zu werden.",
          "<strong>Der Feng-Shui-Impuls:</strong> Das Element Metall unterst\u00fctzt die F\u00fcnf optimal bei der mentalen Kl\u00e4rung und Struktur. Ein aufger\u00e4umter, klarer Norden oder Nordwesten (Bereich f\u00fcr Wissen und hilfreiche Freunde) hilft ihr, gedanklich geerdet zu bleiben, w\u00e4hrend dezente Blaut\u00f6ne (Wasser-Element) die unruhige Mentalt\u00e4tigkeit k\u00fchlen und beruhigen.",
        ]},
        { typ: 6, titel: "Der Loyale \u2013 Die uneinnehmbare Festung", punkte: [
          "<strong>Das Wohnkonzept:</strong> F\u00fcr die sicherheitsorientierte Sechs muss das Zuhause absoluten Schutz bieten. Das zeigt sich in stabilen T\u00fcren, guten Schl\u00f6ssern, einer aufger\u00e4umten, verl\u00e4sslichen Struktur und oft auch praktischen Vorratshaltungen.",
          "<strong>Die Raum-Psychologie:</strong> Kuschelige, gesch\u00fctzte Ecken (wo man den Raum gut im Blick hat, ohne selbst sofort gesehen zu werden \u2013 das sogenannte \u203aH\u00f6hlen-Prinzip\u2039), warme Erdt\u00f6ne und vertraute, stabile M\u00f6bel vermitteln der Sechs das Gef\u00fchl von Bodenhaftung und Absicherung gegen unvorhergesehene Krisen.",
          "<strong>Der Feng-Shui-Impuls:</strong> Hier st\u00e4rkt das Element Erde (stabile M\u00f6bel, keramische T\u00f6pfe, erdige Wandfarben im Zentrum oder S\u00fcdwesten) das Sicherheitsgef\u00fchl. Wichtig im Feng Shui f\u00fcr die Sechs: keine Sitzm\u00f6bel mit dem R\u00fccken zur offenen T\u00fcr platzieren (immer die \u203aBefehlsposition\u2039 einnehmen), um das unbewusste Misstrauen und die Wachsamkeit zu senken.",
        ]},
        { typ: 7, titel: "Der Enthusiast \u2013 Das bunte, offene Studio", punkte: [
          "<strong>Das Wohnkonzept:</strong> Die Sieben liebt Freiheit, Optionen und Inspiration. Einengende, dunkle R\u00e4ume sind f\u00fcr sie der Albtraum. Ihr Wohnstil ist eklektisch, lebendig, voller Erinnerungen an Reisen und offener, lichtdurchfluteter Fl\u00e4chen.",
          "<strong>Die Raum-Psychologie:</strong> Gro\u00dfe Fenster, helle Farben, wechselnde Dekorationen und vielleicht eine kreative Ecke f\u00fcr neue Projekte spiegeln den Drang der Sieben nach Abwechslung wider. Das Zuhause ist hier kein Kokon, sondern eine sprudelnde Basisstation f\u00fcr das n\u00e4chste Erlebnis.",
          "<strong>Der Feng-Shui-Impuls:</strong> Das Element Holz (frische Pflanzen, vertikale Linien, Wachstum) und das Element Feuer (gute Beleuchtung, lebendige Farben) bringen die n\u00f6tige Aufw\u00e4rtsenergie. Im Feng Shui sollte die Sieben jedoch darauf achten, nicht zu viele unvollendete Projekte (Chaos im Chi-Fluss) anzuh\u00e4ufen, sondern gezielt Kraftpunkte zu setzen, um innere Ruhe zu finden.",
        ]},
      ]
    },
    {
      zentrum: "Das Bauch-Zentrum (Typ 8, 9, 1): Raum beanspruchen, Frieden und klare Ordnung",
      intro: "Das instinktgetriebene Bauch-Zentrum ringt mit den Themen Kontrolle, Wut und Autonomie. Die Wohnr\u00e4ume dieser Typen spiegeln wider, wie sie ihren Platz im Raum behaupten oder wie sie Harmonie herstellen.",
      typen: [
        { typ: 8, titel: "Der Herausforderer \u2013 Das kraftvolle Headquarter", punkte: [
          "<strong>Das Wohnkonzept:</strong> Die Acht nimmt Raum ein \u2013 und das zeigt sich auch im Wohnstil. Sie liebt gro\u00dfz\u00fcgige Schnitte, kr\u00e4ftige, markante Farben (wie dunkles Holz, Leder oder kr\u00e4ftiges Anthrazit) und robuste, langlebige M\u00f6bel von hoher Qualit\u00e4t.",
          "<strong>Die Raum-Psychologie:</strong> Der Esszimmertisch oder ein gro\u00dfer Konferenztisch ist oft das Zentrum, an dem man zusammenkommt. Die Acht braucht ein Zuhause, das St\u00e4rke ausstrahlt, in dem sie die Kontrolle beh\u00e4lt und in dem es klare, unmissverst\u00e4ndliche Grenzen gibt (kein verspielter Kitsch, sondern ehrliche, massive Materialien).",
          "<strong>Der Feng-Shui-Impuls:</strong> Das Element Metall und kr\u00e4ftige Erd-Elemente (massive Steine, schwere M\u00f6bel) erden die durchsetzungsstarke Acht. Im Feng Shui ist f\u00fcr sie der Bereich des Karriere- und Lebensweges oder der Machtbereich im Bagua wichtig. Wichtig ist hier, ab und zu das Element Wasser (z. B. ein leises Zimmerbrunnen-Element) zu integrieren, um die lodernde Willenskraft und potenzielle H\u00e4rte symbolisch abzuk\u00fchlen und geschmeidiger zu machen.",
        ]},
        { typ: 9, titel: "Der Vermittler \u2013 Die Oase des Friedens", punkte: [
          "<strong>Das Wohnkonzept:</strong> Die Neun sehnt sich nach absoluter Harmonie und Stressfreiheit. Ihr Wohnstil ist gem\u00fctlich, unaufdringlich und flie\u00dfend. Es gibt keine harten Kanten oder Konflikte im Raumdesign.",
          "<strong>Die Raum-Psychologie:</strong> Sanfte Pastellt\u00f6ne, flauschige Teppiche, viele Kissen und Decken sowie bequeme Sofas machen den Raum zu einer echten Kuscheloase. Alles ist darauf ausgerichtet, zur Ruhe zu kommen, den inneren Frieden zu wahren und Spannungen gar nicht erst aufkommen zu lassen.",
          "<strong>Der Feng-Shui-Impuls:</strong> Das Element Erde (Sanftheit, Geborgenheit) und flie\u00dfende Wasser-Elemente dominieren. Allerdings besteht im Feng Shui bei zu viel Bequemlichkeit die Gefahr von stagnierendem Chi (Tr\u00e4gheit). Die Neun profitiert daher von gezielten Feuer-Impulsen (z. B. roten Kerzen, lebendigem Licht), die sanft aktivieren, ohne die Harmonie zu zerst\u00f6ren, und ihr helfen, die eigene Tatkraft nicht einzuschl\u00e4fern.",
        ]},
        { typ: 1, titel: "Der Perfektionist \u2013 Das makellose Atelier", punkte: [
          "<strong>Das Wohnkonzept:</strong> Ordnung ist f\u00fcr die Eins das halbe Leben. Ihr Zuhause zeichnet sich durch kompromisslose Sauberkeit, Symmetrie und funktionale \u00c4sthetik aus. Jedes Ding hat seinen logischen Platz.",
          "<strong>Die Raum-Psychologie:</strong> Klare geometrische Formen, makellose Oberfl\u00e4chen und ein durchdachtes Beleuchtungskonzept geben der Eins das beruhigende Gef\u00fchl von Kontrolle und moralischer Integrit\u00e4t. Hier herrscht kein Chaos \u2013 weder im Regal noch im Kopf.",
          "<strong>Der Feng-Shui-Impuls:</strong> Das Element Metall (Pr\u00e4zision, Ordnung, wei\u00dfe und graue Nuancen) unterstreicht das Bed\u00fcrfnis nach Struktur perfekt. Im Feng Shui sollte die Eins jedoch darauf achten, dass die Perfektion nicht zu starr und k\u00fchl wirkt (totes Chi). Das gezielte Einbringen von lebendigen Holz-Elementen (wie echten, organisch gewachsenen Pflanzen) bringt den n\u00f6tigen Hauch von Nachsicht, Lebendigkeit und organischer Unvollkommenheit in den Raum.",
        ]},
      ]
    },
    {
      zentrum: "Das Herz-Zentrum (Typ 2, 3, 4): Verbundenheit, B\u00fchne und emotionaler Ausdruck",
      intro: "Im Herzzentrum dreht sich alles um Image, Beziehungen und den tiefen Wunsch nach Wertsch\u00e4tzung. Die Wohnr\u00e4ume dieser Typen sind stark emotional aufgeladen und oft als B\u00fchne oder warmes Nest gestaltet.",
      typen: [
        { typ: 2, titel: "Der Helfer \u2013 Das offene Willkommens-Zuhause", punkte: [
          "<strong>Das Wohnkonzept:</strong> Das Zuhause der Zwei ist f\u00fcr andere da. Es ist ein einladender, warmer Ort, an dem sich G\u00e4ste sofort wie zu Hause f\u00fchlen sollen. \u00dcberall gibt es gem\u00fctliche Sitzgelegenheiten, Kaffeebars und pers\u00f6nliche Geschenke.",
          "<strong>Die Raum-Psychologie:</strong> Warme Lichtquellen, pers\u00f6nliche Fotos von lieben Menschen und eine gastfreundliche Atmosph\u00e4re spiegeln den Wunsch der Zwei wider, gebraucht zu werden und Verbundenheit zu stiften. Oft neigt sie dazu, den eigenen Bedarf hinter den Komfort der G\u00e4ste zu stellen.",
          "<strong>Der Feng-Shui-Impuls:</strong> Das Element Feuer (gem\u00fctliches Licht, herzliche Farben wie Rosa, Pfirsich oder sanftes Rot im Beziehungs-Bagua-Bereich) aktiviert die Herzensenergie. Wichtig im Feng Shui f\u00fcr die Zwei: auch einen gesch\u00fctzten \u203aprivaten R\u00fcckzugsraum\u2039 (z. B. ein intaktes, nur f\u00fcr sie selbst bestimmtes Schlafzimmer-Chi) einrichten, in dem sie sich von der F\u00fcrsorge f\u00fcr andere erholen kann, statt sich im Haus komplett aufzureiben.",
        ]},
        { typ: 3, titel: "Der Erfolgreiche \u2013 Das moderne Designer-Loft", punkte: [
          "<strong>Das Wohnkonzept:</strong> Die Drei legt Wert auf Status, \u00c4sthetik und Effizienz. Ihr Wohnstil ist modern, hochaktuell, oft im angesagten Interior-Design-Trend eingerichtet \u2013 ein Zuhause, das sich sehen lassen kann.",
          "<strong>Die Raum-Psychologie:</strong> Edle Materialien, gl\u00e4nzende Oberfl\u00e4chen, ein top-organisiertes Home-Office und Designer-St\u00fccke zeigen Erfolg und Kompetenz. Hier wird der Wohnraum auch als Visitenkarte genutzt, um Eindruck zu machen und Leistung zu spiegeln.",
          "<strong>Der Feng-Shui-Impuls:</strong> Eine brillante Kombination aus Metall (High-End-Ger\u00e4te, gl\u00e4nzende Akzente) und Feuer (Erfolg, Anerkennung im S\u00fcden des Grundrisses). Im Feng Shui gilt jedoch: Zu viel Hochglanz und reiner Status-Fokus k\u00f6nnen das Herz erkalten lassen (Yang-\u00dcberschuss). Das bewusste Einbinden von beruhigendem Wasser oder sanfter Erde erdet die Drei und erinnert sie daran, dass ein Zuhause kein Vorzeige-Objekt, sondern ein Ort zum Sein sein darf.",
        ]},
        { typ: 4, titel: "Der Individualist \u2013 Das poetische Kunst-Cabinet", punkte: [
          "<strong>Das Wohnkonzept:</strong> Die Vier verabscheut die Stange. Ihr Zuhause ist ein expressives, einzigartiges Gesamtkunstwerk aus Antiquit\u00e4ten, selbstgemachter Kunst, tiefen Farben (wie dunklem Petrol, Samt oder Terrakotta) und atmosph\u00e4rischem Kerzenschein.",
          "<strong>Die Raum-Psychologie:</strong> Jeder Gegenstand hat eine emotionale Geschichte. Die Vier nutzt den Wohnraum als B\u00fchne f\u00fcr ihre reiche Innenwelt, ihre Sehns\u00fcchte und ihre Melancholie. Hier darf es auch mal etwas unaufger\u00e4umt oder dramatisch sein \u2013 Hauptsache, es ist authentisch und voller Seele.",
          "<strong>Der Feng-Shui-Impuls:</strong> Hier dominieren tiefe, geheimnisvolle Wasser- und Holz-Elemente. Im klassischen Feng Shui kann ein Zuviel an schweren, melancholischen Stoffen und dunklen T\u00f6nen jedoch den Energiefluss beschweren (Stagnation). Die Vier profitiert enorm davon, durch gezielte Metall- oder helle Licht-Akzente Klarheit hineinzubringen, damit die emotionale Tiefe nicht in einer dr\u00fcckenden, schwere erzeugenden Raum-Atmosph\u00e4re versinkt.",
        ]},
      ]
    },
  ];

  function typBlock(t) {
    const col = (typeof TYPE_COLORS !== 'undefined' ? TYPE_COLORS[t.typ] : null) || 'var(--copper)';
    return `<div style="border-left:3px solid ${col};padding-left:1.1rem;margin-bottom:1.2rem;">
      <div style="font-size:0.72rem;font-weight:700;letter-spacing:0.1em;text-transform:uppercase;color:${col};margin-bottom:0.4rem;">Typ ${t.typ}</div>
      <h3 style="font-size:1.02rem;font-weight:700;margin:0 0 0.6rem;color:var(--ink);">${t.titel}</h3>
      <ul style="margin:0;padding-left:1.2rem;font-size:0.92rem;line-height:1.7;color:var(--ink);">
        ${t.punkte.map(p => `<li style="margin-bottom:0.5rem;">${p}</li>`).join('')}
      </ul>
    </div>`;
  }

  function zentrumBlock(z, i) {
    return `<div class="vb-section" style="max-width:100%;margin-top:${i === 0 ? '0' : '2rem'};">
      <h2 style="font-size:1.1rem;font-weight:700;margin:0 0 0.8rem;color:var(--ink);">${i + 1}. ${z.zentrum}</h2>
      <p class="vb-intro" style="margin-bottom:1.2rem;">${z.intro}</p>
      ${z.typen.map(typBlock).join('')}
    </div>`;
  }

  return shell(`
    <div class="page-container">
      ${pageHeader('enneagramm-wohnraumarchitektur')}
      <div class="page-content">
        <p class="eyebrow">Wissen \u00b7 Wohnpsychologie</p>
        <h1 class="section-title">Enneagramm meets Wohnraumarchitektur</h1>
        <h2 class="section-title" style="font-size:1.2rem;font-weight:600;margin:0 0 1.4rem;color:var(--muted);">Wohnen im Spiegel der Seele: Die 9 Enneagrammtypen und ihre Architektur des Wohnraums</h2>

        <blockquote class="vb-blockquote" style="margin-bottom:1.8rem;">
          <p class="vb-intro">Unser Zuhause ist weit mehr als nur ein Ort zum Schlafen und Verweilen \u2013 es ist die dreidimensionale Projektion unserer inneren Psyche. Unbewusst gestalten wir unsere Wohnr\u00e4ume so, dass sie unseren tiefsten Sehns\u00fcchten, Schutzmechanismen und Grundmotiven entsprechen. W\u00e4hrend die ganzheitliche Architektur und Wohnpsychologie schon lange untersuchen, wie R\u00e4ume auf uns wirken, l\u00e4sst sich das Enneagramm als faszinierender Schl\u00fcssel nutzen, um die ganz individuellen Wohn- und R\u00fcckzugsbed\u00fcrfnisse der neun Pers\u00f6nlichkeitstypen zu entschl\u00fcsseln.</p>
          <p class="vb-intro">Verbinden wir diese psychologischen Grundmuster zus\u00e4tzlich mit den uralten Weisheiten des Feng Shui \u2013 der Lehre vom harmonischen Fluss der Lebensenergie (Chi) und den f\u00fcnf Elementen (Wasser, Holz, Feuer, Erde, Metall) \u2013, entsteht ein ganzheitlicher Leitfaden f\u00fcr echte Seelen-Kraftorte.</p>
          <p class="vb-intro">Jedes der drei Enneagramm-Zentren (Kopf, Bauch und Herz) und jeder einzelne Typ sucht im Raum nach etwas ganz Bestimmtem: Sicherheit, Kontrolle, Freiheit, \u00c4sthetik oder Harmonie. Eine tiefgehende Betrachtung zeigt, wie sich die Pers\u00f6nlichkeit in W\u00e4nden, M\u00f6beln, Raumstrukturen und dem energetischen Fluss widerspiegelt.</p>
        </blockquote>

        <div style="margin:0 0 2rem;border-radius:12px;overflow:hidden;box-shadow:0 2px 12px rgba(0,0,0,0.15);">
          <img src="./assets/portraits/enneagramm-wohnraumarchitektur-de.jpeg" alt="Enneagramm & Wohnen \u2013 die drei Zentren als Kopf-, Bauch- und Herz-Wohnr\u00e4ume mit Feng-Shui-Elementen" style="width:100%;display:block;" loading="lazy" />
          <p style="text-align:center;font-size:0.78rem;color:var(--muted);margin:0;padding:0.5rem 0.5rem 0.7rem;">Drei Zentren, ein Zuhause: Kopf-Zentrum (Klarheit, Fokus, Ruhe), Bauch-Zentrum (Sicherheit, Genuss, F\u00fclle) und Herz-Zentrum (Verbindung, Ausdruck, Liebe) \u2013 jeweils mit den passenden Feng-Shui-Elementen.</p>
        </div>

        ${ZENTREN_WOHNEN.map(zentrumBlock).join('')}

        <div class="vb-section" style="max-width:100%;margin-top:2rem;">
          <h2 style="font-size:1.1rem;font-weight:700;margin:0 0 0.8rem;color:var(--ink);">Fazit: Wenn der Grundriss zur Pers\u00f6nlichkeit wird</h2>
          <p class="vb-intro">Ein Blick in unsere vier W\u00e4nde zeigt uns oft ehrlicher, wer wir sind, als jedes Fragebogen-Ergebnis. Ob die festungsartige Sicherheit der Sechs, die minimalistische Klarheit der F\u00fcnf, das kunstvolle Nest der Vier oder der flie\u00dfende Friede der Neun \u2013 das Enneagramm in Kombination mit den Prinzipien des Feng Shui hilft uns zu verstehen, warum wir uns in bestimmten R\u00e4umen geborgen und in anderen blockiert f\u00fchlen.</p>
          <p class="vb-intro" style="margin-bottom:0;">Wer sein Zuhause bewusst im Einklang mit seinem Enneagrammtyp und dem optimalen energetischen Chi-Fluss gestaltet, erschafft sich keinen blo\u00dfen Wohnraum, sondern einen echten, lebendigen Kraftort f\u00fcr die Seele.</p>
        </div>

        ${bookTip("wer-du-wirklich-bist-band-1", "Die neun Typen in ihrer Tiefe \u2013 Schutzmuster, Leidenschaften und der Weg zur Essenz. Der erste Band der Trilogie, die das Enneagramm lebendig macht.", "Wer du wirklich bist \u2013 Band 1")}
        ${bookTip("die-27-persoenlichkeiten-des-enneagramms", "27 Charakterprofile im Vergleich \u2013 wie sich die Subtypen desselben Typs voneinander unterscheiden.", "Die 27 Pers\u00f6nlichkeiten des Enneagramms")}
        ${relatedLinks([
          {route:"enneagramm-odyssee", label:"Enneagramm meets Odyssee"},
          {route:"drei-zentren", label:"Schaubild: Drei Zentren"},
          {route:"wunden", label:"Die 9 Wunden der Enneagrammtypen"},
        ])}
      </div>
    </div>
  `);
}

function enneagrammZimmerpflanzenPage() {
  const PFLANZEN_ZENTREN = [
    {
      zentrum: "Das Kopf-Zentrum (Typ 5, 6, 7): Licht, Struktur und bewusste Grenzen",
      intro: "Menschen aus dem Kopf-Zentrum leben im Verstand. Ihre Pflanzen sollten entweder extrem pflegeleicht sein (um keine mentale Zusatzlast zu erzeugen), Stabilit\u00e4t ausstrahlen oder dem Drang nach Abwechslung Raum geben.",
      typen: [
        { typ: 5, titel: "Der Beobachter \u2013 Die Sansevieria (Bogenhanf)", punkte: [
          "Der Bogenhanf ist minimalistisch, extrem gen\u00fcgsam, braucht kaum Wasser und steht f\u00fcr klare, aufrechte Linien. Er gibt im Hintergrund verl\u00e4sslich Sauerstoff ab, ohne sich in den Vordergrund zu dr\u00e4ngen.",
          "Die F\u00fcnf sch\u00e4tzt es, wenn Dinge unkompliziert sind und ihren intellektuellen R\u00fcckzugsort nicht belasten. Der Bogenhanf verzeiht es, wenn man ihn tagelang vergisst \u2013 genau wie die F\u00fcnf in ihren Gedankenwelten versinkt.",
        ]},
        { typ: 6, titel: "Der Loyale \u2013 Der robuste Gummibaum (Ficus elastica)", punkte: [
          "Mit seinen dicken, ledrigen Bl\u00e4ttern und dem kr\u00e4ftigen Stamm strahlt der Gummibaum absolute Verl\u00e4sslichkeit und Verwurzelung aus. Er ist z\u00e4h und \u00fcbersteht auch widrigere Phasen.",
          "Die sicherheitsorientierte Sechs braucht Pflanzen, die nicht sofort bei jedem Pflegefehler die Bl\u00e4tter h\u00e4ngen lassen. Der Gummibaum bietet einen stabilen, sch\u00fctzenden Anker im Raum und symbolisiert Halt und Loyalit\u00e4t.",
        ]},
        { typ: 7, titel: "Der Enthusiast \u2013 Die Monstera Deliciosa (Fensterblatt)", punkte: [
          "Die Monstera w\u00e4chst rasant, ist exotisch, f\u00e4llt durch ihre gro\u00dfen, geschlitzten Bl\u00e4tter auf und liebt das Licht. Sie bringt Dschungel-Feeling und Fernweh in die Wohnung.",
          "Die freiheitsliebende Sieben braucht optische Dynamik und Abwechslung. Die Monstera w\u00e4chst unaufhaltsam in alle Richtungen und spiegelt den experimentierfreudigen, optimistischen und lebendigen Geist der Sieben wider.",
        ]},
      ]
    },
    {
      zentrum: "Das Bauch-Zentrum (Typ 8, 9, 1): Erdung, Sanftheit und klare Form",
      intro: "Das instinktgetriebene Bauch-Zentrum ringt mit Kontrolle, Pr\u00e4senz und innerem Frieden. Die passenden Pflanzen reichen von markanten Kraftpaketen bis hin zu harmonisierenden Begleitern.",
      typen: [
        { typ: 8, titel: "Der Herausforderer \u2013 Die Yucca-Palme oder der Kaktus", punkte: [
          "Dicke, holzige St\u00e4mme, harte Bl\u00e4tter oder wehrhafte Dornen. Diese Pflanzen strahlen pure Ur-Kraft, Widerstandsf\u00e4higkeit und eine nat\u00fcrliche H\u00e4rte aus. Die Acht braucht keine weichen, verletzlichen Gew\u00e4chse.",
          "Eine Yucca oder ein robuster Kaktus unterstreicht die starke, unerschrockene Pr\u00e4senz im Raum. Sie signalisieren klare Grenzen: \u203aHier stehe ich, und ich lasse mich nicht so schnell umwerfen.\u2039",
        ]},
        { typ: 9, titel: "Der Vermittler \u2013 Das Einblatt (Spathiphyllum)", punkte: [
          "Sanfte, geschwungene gr\u00fcne Bl\u00e4tter und rein wei\u00dfe Bl\u00fcten. Das Einblatt gilt im Feng Shui als absoluter Harmonie- und Friedensbringer, der sanft das Raumklima reinigt. Die Neun sehnt sich nach Seelenfrieden und dem Ausgleich von Spannungen \u2013 das Einblatt verstr\u00f6mt eine weiche, beruhigende Energie.",
          "Einziger \u203aTest\u2039 f\u00fcr die Neun: Es zeigt recht schnell durch h\u00e4ngende Bl\u00e4tter, wenn es Durst hat \u2013 ein sanfter Weckruf, achtsam zu bleiben.",
        ]},
        { typ: 1, titel: "Der Perfektionist \u2013 Der Gl\u00fccksbambus oder symmetrische Sukkulenten", punkte: [
          "Exakte geometrische Formen, gerade St\u00e4ngel, klare Struktur, absolut aufger\u00e4umtes Erscheinungsbild ohne wildes, wucherndes Chaos. Die Eins liebt Ordnung und Prinzipien.",
          "Eine Pflanze, die schnurgerade w\u00e4chst und bei der jedes Blatt seinen logischen Platz hat, beruhigt den inneren Kritiker und schenkt das beruhigende Gef\u00fchl von Kontrolle und \u00c4sthetik.",
        ]},
      ]
    },
    {
      zentrum: "Das Herz-Zentrum (Typ 2, 3, 4): Ausdruck, B\u00fchne und emotionale Tiefe",
      intro: "Im Herzzentrum dreht sich alles um Image, Beziehungen und tiefe Gef\u00fchlswelten. Die Pflanzen dieser Typen sind auff\u00e4llig, emotional aufgeladen oder brauchen intensive Zuwendung.",
      typen: [
        { typ: 2, titel: "Der Helfer \u2013 Das Herzblatt-Philodendron (Philodendron scandens)", punkte: [
          "Die Bl\u00e4tter haben die Form von perfekten kleinen Herzen. Die Pflanze w\u00e4chst \u00fcppig, rankt sich liebevoll um Ecken und dankt jede Zuwendung mit sattem, schnellem Wachstum.",
          "Die Zwei gibt gerne Liebe und F\u00fcrsorge. Sich um eine Pflanze zu k\u00fcmmern, deren Bl\u00e4tter buchst\u00e4blich kleine Herzen formen, entspricht ihrem Bed\u00fcrfnis, R\u00e4ume mit Herzensw\u00e4rme und Verbundenheit zu f\u00fcllen.",
        ]},
        { typ: 3, titel: "Der Erfolgreiche \u2013 Die Orchidee (Phalaenopsis)", punkte: [
          "Edle, skulpturale Eleganz, makellose Bl\u00fcten in perfekten Farben. Die Orchidee sieht aus wie ein Designer-Objekt, verlangt aber ein feines Gesp\u00fcr f\u00fcr den richtigen Standort und die passende Pflege.",
          "Die Drei will gl\u00e4nzen und legt Wert auf Status und \u00c4sthetik. Eine pr\u00e4chtige Orchidee im Wohnzimmer ist die perfekte, repr\u00e4sentative Visitenkarte f\u00fcr den eigenen Erfolg und das Gesp\u00fcr f\u00fcr Stil.",
        ]},
        { typ: 4, titel: "Der Individualist \u2013 Die Alocasia (Elefantenohr) oder die Schwarze Katzentreppe", punkte: [
          "Dramatische, fast schon avantgardistische Bl\u00e4tter mit auff\u00e4lligen Adern, manchmal in tiefem Dunkelgr\u00fcn bis Schwarz-Violett. Sie sind etwas z\u00f6gerlicher in der Pflege und verlangen einen Hauch von Hingabe.",
          "Die Vier sucht das Einzigartige, das Melancholische und das Kunstvolle. Eine Alocasia ist keine gew\u00f6hnliche 08/15-Blume, sondern ein echtes Statement mit Charakter, Tiefe und einer Prise Exzentrik.",
        ]},
      ]
    },
  ];

  function pflanzeBlock(t) {
    const col = (typeof TYPE_COLORS !== 'undefined' ? TYPE_COLORS[t.typ] : null) || 'var(--copper)';
    return `<div style="border-left:3px solid ${col};padding-left:1.1rem;margin-bottom:1.2rem;">
      <div style="font-size:0.72rem;font-weight:700;letter-spacing:0.1em;text-transform:uppercase;color:${col};margin-bottom:0.4rem;">Typ ${t.typ}</div>
      <h3 style="font-size:1.02rem;font-weight:700;margin:0 0 0.6rem;color:var(--ink);">${t.titel}</h3>
      <ul style="margin:0;padding-left:1.2rem;font-size:0.92rem;line-height:1.7;color:var(--ink);">
        ${t.punkte.map(p => `<li style="margin-bottom:0.5rem;">${p}</li>`).join('')}
      </ul>
    </div>`;
  }

  function pflanzenZentrumBlock(z, i) {
    return `<div class="vb-section" style="max-width:100%;margin-top:${i === 0 ? '0' : '2rem'};">
      <h2 style="font-size:1.1rem;font-weight:700;margin:0 0 0.8rem;color:var(--ink);">${i + 1}. ${z.zentrum}</h2>
      <p class="vb-intro" style="margin-bottom:1.2rem;">${z.intro}</p>
      ${z.typen.map(pflanzeBlock).join('')}
    </div>`;
  }

  return shell(`
    <div class="page-container">
      ${pageHeader('enneagramm-zimmerpflanzen')}
      <div class="page-content">
        <p class="eyebrow">Wissen \u00b7 Pflanzenpsychologie</p>
        <h1 class="section-title">Enneagramm meets Zimmerpflanzen</h1>
        <h2 class="section-title" style="font-size:1.2rem;font-weight:600;margin:0 0 1.4rem;color:var(--muted);">Gr\u00fcn f\u00fcr die Seele: Die 9 Enneagrammtypen und ihre perfekten Seelen-Pflanzen</h2>

        <blockquote class="vb-blockquote" style="margin-bottom:1.8rem;">
          <p class="vb-intro">Schon beim Betreten einer Wohnung verr\u00e4t oft die erste Pflanze auf der Fensterbank mehr \u00fcber die Bewohnerin oder den Bewohner, als so manches Gespr\u00e4ch es k\u00f6nnte \u2013 der gen\u00fcgsame Bogenhanf im Regal erz\u00e4hlt eine andere Geschichte als die pr\u00e4chtige Orchidee auf dem Esstisch oder die wuchernde Monstera im Erkerfenster. Pflanzen sind stille Mitbewohner, und wie bei jedem Mitbewohner-Verh\u00e4ltnis entscheidet die Chemie zwischen Mensch und Gew\u00e4chs dar\u00fcber, ob daraus eine dauerhafte Beziehung wird oder ein rasch verwelktes Kapitel.</p>
          <p class="vb-intro">Nach der Betrachtung von Wohnr\u00e4umen und Feng Shui im vorigen Kapitel dieses Wissensbereichs lohnt sich der Blick auf eine kleinere, aber nicht minder aufschlussreiche Ebene: die einzelne Pflanze selbst. Jede Pflanze bringt eine ganz eigene Energie, Wachstumsform und Widerstandskraft mit \u2013 von der robusten Sukkulente bis zur zarten, anspruchsvollen Orchidee spiegelt die botanische Welt nahezu jede Facette menschlicher Charaktere wider. Verkn\u00fcpfen wir das Enneagramm \u2013 das tiefenpsychologische Modell der neun Pers\u00f6nlichkeitstypen \u2013 mit der Welt der Zimmerpflanzen, entsteht ein faszinierender Spiegel unserer inneren Bed\u00fcrfnisse.</p>
          <p class="vb-intro">Welche Pflanze passt zur eigenen Struktur? Welche Art von Pflege und Energie entspricht dem eigenen Wesenskern? Eine Betrachtung der neun Typen durch die gr\u00fcne Brille der Botanik.</p>
        </blockquote>

        <div style="margin:0 0 2rem;border-radius:12px;overflow:hidden;box-shadow:0 2px 12px rgba(0,0,0,0.15);">
          <img src="./assets/portraits/enneagramm-zimmerpflanzen-de.jpeg" alt="Enneagramm & Zimmerpflanzen \u2013 die drei Zentren und ihre botanischen Seelen-Entsprechungen" style="width:100%;display:block;" loading="lazy" />
          <p style="text-align:center;font-size:0.78rem;color:var(--muted);margin:0;padding:0.5rem 0.5rem 0.7rem;">Von der gen\u00fcgsamen Sansevieria bis zur dramatischen Alocasia: Neun Zimmerpflanzen als botanisches Spiegelbild der neun Enneagrammtypen.</p>
        </div>

        ${PFLANZEN_ZENTREN.map(pflanzenZentrumBlock).join('')}

        <div class="vb-section" style="max-width:100%;margin-top:2rem;">
          <h2 style="font-size:1.1rem;font-weight:700;margin:0 0 0.8rem;color:var(--ink);">Fazit: Das botanische Spiegelbild</h2>
          <p class="vb-intro">Ob die gen\u00fcgsame Sansevieria der F\u00fcnf, die herzf\u00f6rmige Ranke der Zwei oder die dramatische Alocasia der Vier \u2013 unsere Zimmerpflanzen sind mehr als gr\u00fcne Dekoration. Sie sind lebendige Gef\u00e4hrten, die uns unbewusst genau die Energie spiegeln, die wir in unserem Alltag suchen oder kultivieren wollen.</p>
          <p class="vb-intro" style="margin-bottom:0;">Wer seine Seelen-Pflanze pflegt, tut letztlich immer auch etwas Gutes f\u00fcr das eigene innere Wachstum.</p>
        </div>

        ${bookTip("wer-du-wirklich-bist-band-1", "Die neun Typen in ihrer Tiefe \u2013 Schutzmuster, Leidenschaften und der Weg zur Essenz. Der erste Band der Trilogie, die das Enneagramm lebendig macht.", "Wer du wirklich bist \u2013 Band 1")}
        ${bookTip("archetypen-der-tiere-im-enneagramm", "Wenn Tiere zu Spiegeln der Seele werden \u2013 die archetypische Methode, die sich hier auf die Pflanzenwelt \u00fcbertragen l\u00e4sst.", "Archetypen der Tiere im Enneagramm")}
        ${relatedLinks([
          {route:"baumarten", label:"Baumarten der 9 Typen"},
          {route:"enneagramm-wohnraumarchitektur", label:"Enneagramm meets Wohnraumarchitektur"},
          {route:"enneagramm-kunst", label:"Enneagramm-Kunstgalerie"},
        ])}
      </div>
    </div>
  `);
}

